def _mark_image():
    """PIL image of the mark for the favicon (falls back to an emoji if PIL/WebP is unavailable)."""
    try:
        import base64 as _b64
        import io as _io
        from PIL import Image as _PILImage
        return _PILImage.open(_io.BytesIO(_b64.b64decode("".join(_MARK_B64.split()))))
    except Exception:
        return "🧬"


st.set_page_config(
    page_title="IBDock Provenire — Molecular Docking",
    page_icon=_mark_image(),
    layout="wide",
    initial_sidebar_state="expanded",
)

