_SPLASH_CSS = """
<style>
.ibdock-splash {
    position: fixed; inset: 0; z-index: 2147483647;
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    background: #fdfdff;
    /* Failsafe: if the script ever stalls or errors before dismissal,
       the splash still lifts by itself after 25 s. */
    animation: ibdock-splash-out 0.7s ease 25s forwards;
}
.ibdock-splash.ibdock-splash-hide {
    animation: ibdock-splash-out 0.7s ease 0s forwards;
}
/* Logo = static wordmark (top, multiply-blended so the D / c stay in front)
   + the protein-ligand "o" as separate layers underneath:
     .ibdock-o-pos   positions the layer
       .ibdock-o-glow  soft pulsing glow
       .ibdock-o-dock  one-off "docking" entrance (scale + whirl + fade)
         img           slow endless rotation */
.ibdock-splash .ibdock-logo {
    position: relative; isolation: isolate;
    width: min(720px, 78vw); background: #fdfdff;
    margin-bottom: 5rem;   /* room for the progress block, which is positioned separately */
    animation: ibdock-splash-in 0.8s ease both;
}
.ibdock-splash .ibdock-logo img { display: block; max-width: none; }
.ibdock-splash .ibdock-logo-base {
    position: relative; z-index: 1; width: 100%; height: auto;
    mix-blend-mode: multiply;
}
.ibdock-splash .ibdock-o-pos {
    position: absolute; z-index: 0;
    left: 44.705%; top: 5.082%; width: 27.409%; aspect-ratio: 1 / 1;
}
.ibdock-splash .ibdock-o-glow {
    position: absolute; inset: -22%; border-radius: 50%;
    background: radial-gradient(circle, rgba(30,136,229,0.30) 0%, rgba(30,136,229,0.10) 45%, rgba(30,136,229,0) 70%);
    animation: ibdock-glow 2.8s ease-in-out infinite;
}
.ibdock-splash .ibdock-o-dock {
    position: absolute; inset: 0;
    animation: ibdock-dock 1.25s cubic-bezier(0.2, 0.8, 0.2, 1) 0.25s both;
}
.ibdock-splash .ibdock-logo-protein {
    width: 100%; height: auto; transform-origin: 50% 50%; will-change: transform;
    animation: ibdock-protein-spin 9s linear infinite;
}
/* Progress block: its own element so stage text can be updated without re-sending the images. */
.ibdock-prog {
    position: fixed; left: 50%; transform: translateX(-50%); z-index: 2147483647;
    top: calc(50% + min(720px, 78vw) * 0.19107 - 0.3rem);
    display: flex; flex-direction: column; align-items: center;
    animation: ibdock-splash-out 0.7s ease 25s forwards;
}
.ibdock-prog.ibdock-prog-hide { animation: ibdock-splash-out 0.7s ease 0s forwards; }
.ibdock-prog .ibdock-bar {
    width: min(280px, 50vw); height: 3px; background: #e3ebf5;
    border-radius: 3px; overflow: hidden;
}
.ibdock-prog .ibdock-bar > i {
    display: block; height: 100%; border-radius: 3px;
    background: linear-gradient(90deg, #0a2a5e, #1e88e5);
    transition: width 0.55s ease;
}
.ibdock-prog .ibdock-msg {
    margin-top: 0.9rem; font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
    font-size: 0.78rem; letter-spacing: 0.08em; text-transform: uppercase; color: #5b7090;
}
.ibdock-prog .ibdock-ver {
    margin-top: 1.5rem; font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
    font-size: 0.68rem; letter-spacing: 0.06em; color: #93a3bb;
}
@media (prefers-reduced-motion: reduce) {
    .ibdock-splash .ibdock-logo-protein, .ibdock-splash .ibdock-o-glow,
    .ibdock-splash .ibdock-o-dock { animation: none; }
}
@keyframes ibdock-protein-spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
@keyframes ibdock-dock {
    0%   { opacity: 0; transform: scale(1.3) rotate(-150deg); }
    55%  { opacity: 1; }
    100% { opacity: 1; transform: scale(1) rotate(0deg); }
}
@keyframes ibdock-glow { 0%, 100% { opacity: 0.35; transform: scale(0.92); } 50% { opacity: 0.85; transform: scale(1.06); } }
@keyframes ibdock-splash-in  { from { opacity: 0; transform: scale(0.97); } to { opacity: 1; transform: scale(1); } }
@keyframes ibdock-splash-out { to { opacity: 0; visibility: hidden; pointer-events: none; } }
/* Take the splash's own element containers out of the page flow (no layout gap). */
.element-container:has(.ibdock-splash), .element-container:has(.ibdock-prog),
[data-testid="stElementContainer"]:has(.ibdock-splash),
[data-testid="stElementContainer"]:has(.ibdock-prog) {
    position: absolute; height: 0; margin: 0; padding: 0; overflow: visible;
}
</style>
"""


def _splash_html(hide=False):
    cls = "ibdock-splash ibdock-splash-hide" if hide else "ibdock-splash"
    return (
        _SPLASH_CSS
        + f'<div class="{cls}">'
        + '<div class="ibdock-logo">'
        + '<div class="ibdock-o-pos"><div class="ibdock-o-glow"></div><div class="ibdock-o-dock">'
        + f'<img class="ibdock-logo-protein" alt="" src="data:image/webp;base64,{"".join(_SPLASH_PROTEIN_B64.split())}">'
        + "</div></div>"
        + f'<img class="ibdock-logo-base" alt="IBDock Provenire" src="data:image/webp;base64,{"".join(_SPLASH_LOGO_B64.split())}">'
        + "</div>"
        + "</div>"
    )


def _splash_progress_html(pct, text, hide=False):
    """Small stage/progress block (no images), cheap to re-send on every stage change."""
    cls = "ibdock-prog ibdock-prog-hide" if hide else "ibdock-prog"
    pct = max(0, min(100, int(pct)))
    return (
        f'<div class="{cls}">'
        f'<div class="ibdock-bar"><i style="width:{pct}%"></i></div>'
        f'<div class="ibdock-msg">{_html_escape(text)}</div>'
        f'<div class="ibdock-ver">V{_APP_VERSION} &middot; AutoDock Vina</div>'
        "</div>"
    )


def _html_escape(s):
    return str(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


# Shown once per browser session (not on every Streamlit rerun).
_splash_slot = None
_splash_prog_slot = None
_splash_t0 = time.time()
if not st.session_state.get("_ibdock_splash_done", False):
    _splash_slot = st.empty()
    _splash_slot.markdown(_splash_html(), unsafe_allow_html=True)
    _splash_prog_slot = st.empty()
    _splash_prog_slot.markdown(_splash_progress_html(8, "Starting up"), unsafe_allow_html=True)


def _splash_stage(pct, text):
    """Report real startup progress on the splash (no-op once the splash is gone)."""
    if _splash_prog_slot is not None:
        _splash_prog_slot.markdown(_splash_progress_html(pct, text), unsafe_allow_html=True)


def _dismiss_splash(min_seconds=2.0):
    """Finish the bar, hold the splash for a minimum time, then fade it out (once per session)."""
    global _splash_slot, _splash_prog_slot
    if _splash_slot is None:
        return
    _splash_stage(100, "Ready")
    remaining = min_seconds - (time.time() - _splash_t0)
    time.sleep(max(remaining, 0) + 0.35)   # +0.35 s so the bar visibly reaches 100 %
    _splash_slot.markdown(_splash_html(hide=True), unsafe_allow_html=True)
    if _splash_prog_slot is not None:
        _splash_prog_slot.markdown(_splash_progress_html(100, "Ready", hide=True), unsafe_allow_html=True)
    st.session_state["_ibdock_splash_done"] = True
    _splash_slot = None
    _splash_prog_slot = None


_BUSY_CSS = (
    "<style>"
    ".ibdock-busy{display:flex;align-items:center;gap:0.75rem;margin:0.35rem 0 0.55rem;}"
    ".ibdock-busy svg{height:40px;width:54px;overflow:visible;flex:none;}"
    ".ibdock-busy span{font-family:'Inter','Helvetica Neue',Arial,sans-serif;font-size:0.78rem;"
    "letter-spacing:0.08em;text-transform:uppercase;color:#5b7090;}"
    # protein preparation: rainbow chain draws itself piece by piece (N- to C-terminus), residue nodes pulse
    ".ibdock-pr-p{stroke-dasharray:100;animation:ibdock-pr-draw 4.6s ease-in-out infinite;}"
    "@keyframes ibdock-pr-draw{0%{stroke-dashoffset:100;}20%{stroke-dashoffset:0;}84%{stroke-dashoffset:0;}100%{stroke-dashoffset:-100;}}"
    # ligand preparation: ring draws itself and un-draws, atoms pulse in turn
    ".ibdock-lg-ring{stroke-dasharray:66;animation:ibdock-lg-draw 2.6s ease-in-out infinite;}"
    ".ibdock-lg-atom{transform-box:fill-box;transform-origin:center;animation:ibdock-lg-pulse 2.6s ease-in-out infinite;}"
    "@keyframes ibdock-lg-draw{0%{stroke-dashoffset:66;}50%{stroke-dashoffset:0;}100%{stroke-dashoffset:-66;}}"
    "@keyframes ibdock-lg-pulse{0%,100%{transform:scale(0.7);}50%{transform:scale(1.3);}}"
    # docking: ligand glides into the receptor pocket, wiggles, glows, repeats
    ".ibdock-dk-lig{animation:ibdock-dk 2.8s ease-in-out infinite;}"
    ".ibdock-dk-ring{transform-box:fill-box;transform-origin:center;animation:ibdock-dk-r 2.8s ease-out infinite;}"
    "@keyframes ibdock-dk{0%{transform:translate(-4px,0);opacity:0;}12%{transform:translate(0,0);opacity:1;}"
    "55%{transform:translate(29px,0);}62%{transform:translate(29px,-1.6px);}70%{transform:translate(29px,1.3px);}"
    "80%{transform:translate(29px,0);opacity:1;}100%{transform:translate(29px,0);opacity:0;}}"
    "@keyframes ibdock-dk-r{0%,52%{transform:scale(0.4);opacity:0;}56%{opacity:0.85;}90%,100%{transform:scale(3.2);opacity:0;}}"
    # configuration gear (sidebar)
    ".ibdock-gear{transform-box:fill-box;transform-origin:center;animation:ibdock-gear 16s linear infinite;}"
    "@keyframes ibdock-gear{to{transform:rotate(360deg);}}"
    "@media (prefers-reduced-motion: reduce){.ibdock-pr-p,.ibdock-lg-ring,"
    ".ibdock-lg-atom,.ibdock-dk-lig,.ibdock-dk-ring,.ibdock-gear{animation:none;}}"
    "</style>"
)


def _svg_protein():
    """Protein preparation: a simple rainbow protein (helix - beta hairpin - helix) that draws itself, N- to C-terminus."""
    import math

    def coil(x0, pitch, ax, ay, yc, ta, tb, steps=26):
        pts = []
        n = max(2, int(steps * (tb - ta)))
        for k in range(n + 1):
            t = 2 * math.pi * (ta + (tb - ta) * k / n)
            pts.append((x0 + pitch * t / (2 * math.pi) - ax * math.sin(t), yc + ay * math.cos(t)))
        return "M" + " L".join(f"{x:.2f} {y:.2f}" for x, y in pts)

    pieces = [  # (path, colour) in chain order, N- to C-terminus
        ("M3 16 C2 26 6 33 10 34.5", "#2b4fe0"),
        (coil(10, 6.5, 3.0, 7.5, 27, 0.0, 1.25), "#2f6df0"),
        (coil(10, 6.5, 3.0, 7.5, 27, 1.25, 2.5), "#17a8e8"),
        ("M26.25 19.5 C27 32 29 41 33 38", "#1fb89a"),
        ("M33 38 L33 14 M29 19 L33 13 L37 19", "#34b84a"),
        ("M33 13 C33 6 40 4 40 10", "#8bc43a"),
        ("M40 10 L40 34 M36 29 L40 35 L44 29", "#e6c21a"),
        ("M40 35 C40 43 46 43 47 34", "#f4a21c"),
        (coil(47, 6.2, 2.8, 7.0, 27, 0.0, 1.1), "#f57c1f"),
        (coil(47, 6.2, 2.8, 7.0, 27, 1.1, 2.25), "#e5342b"),
    ]
    cycle, step = 4.6, 0.17
    out = ["<svg viewBox='0 0 64 48' xmlns='http://www.w3.org/2000/svg'>"]
    for i, (d, col) in enumerate(pieces):
        out.append(
            f"<path class='ibdock-pr-p' pathLength='100' d='{d}' fill='none' stroke='{col}' stroke-width='2.4' "
            f"stroke-linecap='round' stroke-linejoin='round' style='animation-delay:{i * step - cycle:.2f}s'/>"
        )
    nodes = [(3, 16, "#2b4fe0"), (26.25, 19.5, "#17a8e8"), (33, 38, "#34b84a"), (43.1, 40.9, "#f4a21c"), (58.15, 27, "#e5342b")]
    for i, (x, y, col) in enumerate(nodes):
        out.append(f"<circle class='ibdock-lg-atom' cx='{x}' cy='{y}' r='2.1' fill='{col}' style='animation-delay:-{2.6 - i * 0.43:.2f}s'/>")
    out.append("</svg>")
    return "".join(out)


def _svg_ligand():
    """Ligand preparation: a small-molecule ring that draws itself while its atoms pulse."""
    v = [(24, 13), (33.53, 18.5), (33.53, 29.5), (24, 35), (14.47, 29.5), (14.47, 18.5)]
    pts = " ".join(f"{x},{y}" for x, y in v)
    parts = ["<svg viewBox='0 0 48 48' xmlns='http://www.w3.org/2000/svg'>",
             f"<polygon class='ibdock-lg-ring' points='{pts}' fill='none' stroke='#1e88e5' stroke-width='1.8' stroke-linejoin='round'/>",
             "<line x1='33.53' y1='18.5' x2='40' y2='14.7' stroke='#1e88e5' stroke-width='1.6'/>",
             "<line x1='14.47' y1='29.5' x2='8' y2='33.3' stroke='#1e88e5' stroke-width='1.6'/>"]
    for i, (x, y) in enumerate(v):
        col = "#0a2a5e" if i % 2 == 0 else "#1e88e5"
        parts.append(f"<circle class='ibdock-lg-atom' cx='{x}' cy='{y}' r='2.4' fill='{col}' style='animation-delay:-{2.6 - i * 0.43:.2f}s'/>")
    parts.append("<circle class='ibdock-lg-atom' cx='40' cy='14.7' r='2.6' fill='#e53935' style='animation-delay:-1.1s'/>")
    parts.append("<circle class='ibdock-lg-atom' cx='8' cy='33.3' r='2.6' fill='#26c6da' style='animation-delay:-0.4s'/>")
    parts.append("</svg>")
    return "".join(parts)


def _svg_dock():
    """Docking: a ligand glides into the receptor pocket."""
    arc = "M30.5 14.4 A15 15 0 1 1 30.5 33.6"
    return (
        "<svg viewBox='0 0 64 48' xmlns='http://www.w3.org/2000/svg'>"
        f"<path d='{arc}' fill='none' stroke='#0a2a5e' stroke-width='6' stroke-linecap='round'/>"
        f"<path d='{arc}' fill='none' stroke='#1e88e5' stroke-width='2' stroke-linecap='round' opacity='0.8'/>"
        "<circle class='ibdock-dk-ring' cx='41' cy='24' r='4' fill='none' stroke='#1e88e5' stroke-width='1.5'/>"
        "<g class='ibdock-dk-lig'>"
        "<polyline points='8,26 12,22 16,26' fill='none' stroke='#5b7090' stroke-width='1.5' stroke-linejoin='round'/>"
        "<circle cx='8' cy='26' r='2.4' fill='#26c6da'/><circle cx='12' cy='22' r='2.6' fill='#1e88e5'/>"
        "<circle cx='16' cy='26' r='2.4' fill='#e53935'/>"
        "</g></svg>"
    )


def _svg_gear():
    """Configuration: a gently turning gear."""
    return (
        "<svg viewBox='0 0 28 28' xmlns='http://www.w3.org/2000/svg' style='width:26px;height:26px;'>"
        "<g class='ibdock-gear' fill='none' stroke='#1e5aa8'>"
        "<circle cx='14' cy='14' r='11.2' stroke-width='3.6' stroke-dasharray='4.4 4.4'/>"
        "<circle cx='14' cy='14' r='8.6' stroke-width='3'/>"
        "<circle cx='14' cy='14' r='2.8' stroke-width='2'/>"
        "</g></svg>"
    )


_BUSY_SVGS = {"protein": _svg_protein, "ligand": _svg_ligand, "dock": _svg_dock}


def _busy_html(label, kind="dock"):
    """Themed animation + label, shown while a run is in progress (kind: protein | ligand | dock)."""
    svg = _BUSY_SVGS.get(kind, _svg_dock)()
    return _BUSY_CSS + f'<div class="ibdock-busy">{svg}<span>{_html_escape(label)}</span></div>'


def _busy_start(label, kind="dock"):
    """Show the themed animation; call .empty() on the returned slot when the run is finished."""
    slot = st.empty()
    slot.markdown(_busy_html(label, kind), unsafe_allow_html=True)
    return slot


