# ──────────────────────────────────────────────────────────────────────────────
# CONSTANTS
# ──────────────────────────────────────────────────────────────────────────────
METAL_IONS = {"ZN", "MG", "FE", "CA", "MN", "CU", "K", "NA", "NI", "CO",
              "CD", "HG", "PT", "AU", "AG", "BA", "SR", "LI", "RB", "CS"}

# Residue names that are NEVER a drug-like co-crystallised ligand.
# These are crystallographic additives, buffer components, solvents, ions,
# and cryoprotectants that appear as HETATM records in PDB files.
# When computing the grid box centre from co-crystallised ligands, all of
# these are excluded so only the true drug-like ligand(s) are used.
EXCLUDE_RESNAMES = {
    # Water
    "HOH", "WAT", "H2O", "DOD",
    # Ions — monatomic
    "NA",  "MG",  "K",   "CA",  "MN",  "FE",  "CO",  "NI",  "CU",  "ZN",
    "SE",  "BR",  "CD",  "I",   "CS",  "BA",  "HG",  "PT",  "AU",  "AG",
    "LI",  "RB",  "SR",  "PB",  "TL",  "IN",  "YB",  "SM",  "TB",  "GD",
    "CL",  "F",   "IOD",
    # Common polyatomic ions / buffer salts
    "SO4", "PO4", "NO3", "ACT", "ACY", "FMT", "SUC", "TRS", "MES",
    "HEP", "EPE", "BIS", "CIT", "TAR", "OXL", "MLT", "PHO",
    # Cryoprotectants and precipitants
    "GOL", "GLY", "PG4", "PGE", "PG6", "PEG", "PE4", "P6G", "1PE", "2PE",
    "EDO", "EGL", "MPD", "IPA", "EOH", "ACE", "ACN", "DMS", "MSO",
    "DMF", "DMU", "IMD",
    # Reducing agents and their reaction adducts with surface cysteines —
    # NOT ligands; excluding them prevents false grid-centroid shifts.
    "BME", "CME", "DTT", "TCEP", "MRD", "B3P", "BTB", "PGO",
    # Detergents common in membrane protein crystals
    "BOG", "DDM", "OG",  "NG",  "LMT", "LDA",
    # Polyamines / crystallisation additives
    "SPD", "SPM", "PUT",
    # Monosaccharides often added to buffers
    "XYL", "FRU", "GAL", "MAN", "FUC",
}


# ──────────────────────────────────────────────────────────────────────────────
# HELPER UTILITIES
# ──────────────────────────────────────────────────────────────────────────────

def _obabel_env(obabel_path: str | None = None):
    """Return an environment for bundled Open Babel on Windows.

    Open Babel 3.x needs BABEL_DATADIR to locate bundled data files such as
    space-groups.txt when launched from a portable application directory.
    The executable directory is also prepended to PATH so its DLLs/plugins
    are resolved from the bundled installation.
    """
    env = os.environ.copy()
    if obabel_path:
        obabel_exe = Path(obabel_path).resolve()
        obabel_dir = obabel_exe.parent
        data_dir = obabel_dir / "data"
        if data_dir.exists():
            env["BABEL_DATADIR"] = str(data_dir)
        env["PATH"] = str(obabel_dir) + os.pathsep + env.get("PATH", "")
    return env


def run_cmd(cmd: list, timeout: float | None = None):
    """Run a subprocess command, configuring bundled Open Babel when used."""
    cmd_str = [str(c) for c in cmd]
    env = None
    if cmd_str:
        try:
            exe = Path(cmd_str[0]).resolve()
            if exe.name.lower() == "obabel.exe" or exe.name.lower() == "obabel":
                env = _obabel_env(cmd_str[0])
        except Exception:
            pass
    subprocess.run(
        cmd_str,
        check=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        shell=False,
        env=env,
        timeout=timeout,
    )


def validate_tool(path_str: str, label: str) -> dict:
    """Validate a native external tool."""
    result = {"label": label, "ok": False, "version": None, "detail": ""}

    if not path_str or not path_str.strip():
        result["detail"] = "Path not specified"
        return result

    path = Path(path_str.strip())

    if path.suffix.lower() == ".py":
        if path.exists():
            result["ok"] = True
            result["detail"] = f"Script found ✔  ({path.stat().st_size:,} bytes)"
        else:
            result["detail"] = f"File not found: {path}"
        return result

    if not path.exists():
        result["detail"] = f"File not found: {path}"
        return result

    if path.suffix.lower() not in {".bat", ".cmd"} and not os.access(str(path), os.X_OK):
        result["detail"] = f"File exists but is not executable: {path}"
        return result

    for flag in ["--version", "-version", "--help", ""]:
        try:
            cmd = [str(path)] + ([flag] if flag else [])
            if path.suffix.lower() in {".bat", ".cmd"}:
                cmd = ["cmd.exe", "/c"] + cmd
            proc = subprocess.run(
                cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                text=True, timeout=10, shell=False
            )
            out = (proc.stdout + proc.stderr).strip()
            if out:
                result["version"] = next(
                    (l for l in out.splitlines() if l.strip()), ""
                )[:120]
                break
        except Exception:
            continue

    result["ok"] = True
    result["detail"] = "Executable found and runs ✔"
    return result


# ──────────────────────────────────────────────────────────────────────────────
# STRUCTURE HELPERS
# ──────────────────────────────────────────────────────────────────────────────

# ── Flag vocabularies (used only to LABEL candidates in Manual ligand selection;
#    nothing is hidden because of these lists) ────────────────────────────────
WATER_RESNAMES = {"HOH", "WAT", "H2O", "DOD"}

KNOWN_COFACTORS = {
    "HEM", "HEC", "HEA", "HEB", "NAD", "NAP", "NDP", "NAI", "FAD", "FMN",
    "ATP", "ADP", "AMP", "ANP", "GTP", "GDP", "GNP", "SAH", "SAM", "PLP",
    "COA", "ACO", "TPP", "CLA", "CHL", "BCL", "H4B", "BH4", "FES", "SF4",
    "F3S", "MGD", "PQQ", "THF",
}
GLYCAN_RESNAMES = {
    "NAG", "NDG", "BMA", "MAN", "FUC", "GAL", "GLC", "BGC", "SIA", "A2G",
    "NGA", "XYS", "FUL", "MAG", "NA2",
}
STANDARD_AA = {
    "ALA", "ARG", "ASN", "ASP", "CYS", "GLN", "GLU", "GLY", "HIS", "ILE",
    "LEU", "LYS", "MET", "PHE", "PRO", "SER", "THR", "TRP", "TYR", "VAL",
}
LOW_CONTACT_THRESHOLD = 15   # protein atoms within 4.5 A; below this → "few contacts"


def _het_key(line: str) -> tuple:
    """Residue-instance key of a PDB line: (resname, chain, resseq, icode)."""
    return (line[17:20].strip(), line[21:22].strip(),
            line[22:26].strip(), line[26:27].strip())


def _lig_id(key: tuple) -> str:
    rn, ch, num, ic = key
    return f"{rn} {ch or '_'}:{num}{ic}"


def parse_modres_and_links(lines: list):
    """Return (modified_residue_names, covalently_linked_residue_keys).

    MODRES records identify modified amino acids (MSE, SEP, TPO, ...) that
    are HETATM in the file but belong to the protein chain, not ligands.
    LINK records identify HETATM residues covalently bonded to a standard
    amino acid (covalent inhibitors, N-linked glycans).
    """
    modres, covalent = set(), set()
    for line in lines:
        if line.startswith("MODRES"):
            modres.add(line[12:15].strip())
        elif line.startswith("LINK") and len(line) >= 57:
            k1 = (line[17:20].strip(), line[21:22].strip(),
                  line[22:26].strip(), line[26:27].strip())
            k2 = (line[47:50].strip(), line[51:52].strip(),
                  line[52:56].strip(), line[56:57].strip())
            if k1[0] in STANDARD_AA:
                covalent.add(k2)
            if k2[0] in STANDARD_AA:
                covalent.add(k1)
    return modres, covalent


def _count_contacts(lig_xyz: np.ndarray, prot_xyz: np.ndarray, cutoff: float = 4.5) -> int:
    """Number of distinct protein atoms within `cutoff` A of any ligand atom."""
    if prot_xyz.size == 0 or lig_xyz.size == 0:
        return 0
    mask = np.zeros(len(prot_xyz), dtype=bool)
    c2 = cutoff * cutoff
    for p in lig_xyz:
        mask |= ((prot_xyz - p) ** 2).sum(axis=1) <= c2
    return int(mask.sum())


def enumerate_ligand_candidates(lines: list, include_small: bool = False,
                                min_heavy_atoms: int = 7) -> list:
    """List every HETATM residue instance that could be a co-crystallised ligand.

    Used by Manual ligand selection. Unlike extract_ligand_atoms() nothing is
    pooled: each residue instance (resname + chain + residue number) is its
    own entry with heavy-atom count, protein-contact count and FLAGS
    (cofactor, glycan, covalent, additive/ion, small fragment, few contacts).
    Flagged entries are still listed and selectable.

    Always skipped: water, and modified amino acids named in MODRES records
    (they are part of the protein). Skipped unless include_small=True: ions /
    buffers / cryoprotectants (EXCLUDE_RESNAMES) and residues with fewer than
    min_heavy_atoms heavy atoms. Only the first alternate location is used.

    Each dict has: id, key, resname, chain, resnum, n_heavy, contacts, flags,
    suggested, xyz (Nx3), centroid.
    """
    from collections import OrderedDict

    modres, covalent = parse_modres_and_links(lines)
    residues = OrderedDict()
    for line in lines:
        if not line.startswith("HETATM"):
            continue
        rn = line[17:20].strip()
        if rn in WATER_RESNAMES or rn in modres:
            continue
        if not include_small and rn in EXCLUDE_RESNAMES:
            continue
        if line[16:17] not in ("", " ", "A", "1"):      # keep first altloc only
            continue
        element = line[76:78].strip().upper()
        name    = line[12:16].strip().upper()
        if element in ("H", "D") or (not element and name.startswith(("H", "D"))):
            continue
        try:
            xyz = (float(line[30:38]), float(line[38:46]), float(line[46:54]))
        except ValueError:
            continue
        residues.setdefault(_het_key(line), []).append(xyz)

    prot_xyz = extract_protein_atoms(lines)
    cands = []
    for key, xyzs in residues.items():
        rn, n = key[0], len(xyzs)
        if not include_small and n < min_heavy_atoms:
            continue
        arr = np.array(xyzs)
        contacts = _count_contacts(arr, prot_xyz)
        flags = []
        if rn in KNOWN_COFACTORS:
            flags.append("cofactor")
        if rn in GLYCAN_RESNAMES:
            flags.append("glycan")
        elif key in covalent and rn not in METAL_IONS and n > 1:
            flags.append("covalent")
        if rn in EXCLUDE_RESNAMES:
            flags.append("additive/ion")
        elif n < min_heavy_atoms:
            flags.append("small fragment")
        if contacts < LOW_CONTACT_THRESHOLD:
            flags.append("few contacts")
        cands.append(dict(id=_lig_id(key), key=key, resname=rn, chain=key[1],
                          resnum=key[2] + key[3], n_heavy=n, contacts=contacts,
                          flags=flags, suggested=False, xyz=arr,
                          centroid=arr.mean(axis=0)))

    # Suggested pre-selection: the best-buried candidate that carries none of
    # the "probably not the target ligand" flags. Just a default; the user
    # can change it.
    _bad = {"cofactor", "glycan", "additive/ion", "small fragment", "few contacts"}
    clean = [c for c in cands if not (_bad & set(c["flags"]))]
    if clean:
        max(clean, key=lambda c: c["contacts"])["suggested"] = True
    return cands


def select_ligand_atoms(lines: list, selected_ids, include_small: bool = False):
    """Manual-mode counterpart of extract_ligand_atoms().

    Returns (coords, resnames, residue_keys, all_candidates) for exactly the
    ligands whose id is in selected_ids; coords is an empty array when
    nothing is selected.
    """
    cands  = enumerate_ligand_candidates(lines, include_small=include_small)
    wanted = set(selected_ids or [])
    chosen = [c for c in cands if c["id"] in wanted]
    if not chosen:
        return np.array([]), set(), set(), cands
    coords = np.vstack([c["xyz"] for c in chosen])
    return coords, {c["resname"] for c in chosen}, {c["key"] for c in chosen}, cands


_LIG_FLAG_STYLE = {
    "cofactor":       ("info", "Known enzyme cofactor or prosthetic group"),
    "glycan":         ("info", "Sugar residue, usually from glycosylation"),
    "covalent":       ("info", "Covalently bonded to a protein residue (PDB LINK record)"),
    "additive/ion":   ("mute", "Crystallisation additive, buffer component or ion"),
    "small fragment": ("warn", "Fewer than 7 heavy atoms"),
    "few contacts":   ("warn", f"Fewer than {LOW_CONTACT_THRESHOLD} protein atoms within 4.5 Å - probably surface-bound"),
}


def _lig_tag(text: str, cls: str, title: str = "") -> str:
    import html as _html
    return (f'<span class="lig-tag {cls}" title="{_html.escape(title, quote=True)}">'
            f'{_html.escape(text)}</span>')


def ligand_legend_html() -> str:
    """One-line legend of all flags (hover a tag for its meaning)."""
    return "".join(_lig_tag(f, cls, tip) for f, (cls, tip) in _LIG_FLAG_STYLE.items())


def render_ligand_table_html(cands: list, selected_ids=None) -> str:
    """Candidate table as app-styled HTML (single line: Markdown-safe)."""
    import html as _html
    sel = set(selected_ids or [])
    max_c = max([c["contacts"] for c in cands] + [1])
    rows = []
    for c in cands:
        tags = "".join(_lig_tag(f, *_LIG_FLAG_STYLE.get(f, ("mute", ""))) for f in c["flags"])
        tags = tags or '<span style="color:#aaa;">&mdash;</span>'
        sug = ('<span style="margin-left:8px;">'
               + _lig_tag("suggested", "ok", "Best-buried candidate without warning flags")
               + "</span>") if c["suggested"] else ""
        bar = f'<span class="lig-bar" style="width:{int(round(40 * c["contacts"] / max_c))}px"></span>'
        rows.append(
            f'<tr class="{"sel" if c["id"] in sel else ""}">'
            f'<td><span class="lid">{_html.escape(c["id"])}</span>{sug}</td>'
            f'<td class="num">{c["n_heavy"]}</td>'
            f'<td class="num">{bar}{c["contacts"]}</td>'
            f'<td>{tags}</td></tr>'
        )
    return (
        '<table class="lig-table"><thead><tr><th>Ligand</th>'
        '<th class="num">Heavy atoms</th><th class="num">Protein contacts &le;4.5 &Aring;</th>'
        '<th>Flags</th></tr></thead><tbody>' + "".join(rows) + '</tbody></table>'
    )


@st.cache_data(show_spinner=False)
def _scan_ligands_cached(pdb_path: str, mtime: float, include_small: bool) -> list:
    """Cached per-file candidate scan (mtime busts the cache when a PDB changes)."""
    lines = Path(pdb_path).read_text().splitlines(keepends=True)
    return enumerate_ligand_candidates(lines, include_small=include_small)


def extract_ligand_atoms(lines: list, min_heavy_atoms: int = 7):
    """Return (coords_array, resnames_set) for drug-like co-crystallised ligand atoms.

    This is the AUTOMATIC selection. Filtering strategy (in order):
    1. Skip any residue name in EXCLUDE_RESNAMES (ions, solvents, buffers,
       cryoprotectants) and modified amino acids listed in MODRES records.
       Only the first alternate location of each atom is used.
    2. Group remaining HETATM records by residue INSTANCE (resname, chain,
       residue number, insertion code) and count heavy atoms per instance.
    3. Skip any instance whose heavy atom count is below min_heavy_atoms
       (default 7): small crystallographic additives not in EXCLUDE_RESNAMES.
    4. Restrict to a SINGLE chain: when a structure contains multiple
       crystallographic copies of the complex, pooling ligand coordinates
       from every chain gives a centroid that matches no real binding site
       (root cause of a ~10.7 A grid-centering error on PDB 1HVY). Pick the
       single chain with the most qualifying ligand atoms and use only that
       chain's residues - this still allows several co-located HETATM
       residues within ONE binding site to be combined.

    NOTE: residues within the chosen chain are still pooled. If a chain holds
    ligands in DIFFERENT sites, use Manual selection instead.

    Returns a numpy array of (x, y, z) coords and a set of surviving residue names.
    """
    from collections import defaultdict

    modres, _covalent = parse_modres_and_links(lines)
    groups = defaultdict(list)   # (resname, chain, resseq, icode) -> heavy-atom xyz
    for line in lines:
        if not line.startswith("HETATM"):
            continue
        rn = line[17:20].strip()
        if rn in EXCLUDE_RESNAMES or rn in modres:
            continue
        if line[16:17] not in ("", " ", "A", "1"):       # first altloc only
            continue
        atom_name = line[12:16].strip()
        if atom_name.upper().startswith(("H", "D")):
            continue                       # skip hydrogens / deuteriums
        try:
            xyz = (float(line[30:38]), float(line[38:46]), float(line[46:54]))
        except ValueError:
            continue
        groups[_het_key(line)].append(xyz)

    qualifying = {key: xyzs for key, xyzs in groups.items() if len(xyzs) >= min_heavy_atoms}
    if not qualifying:
        return np.array([]), set()

    atoms_per_chain = defaultdict(int)
    for key, xyzs in qualifying.items():
        atoms_per_chain[key[1]] += len(xyzs)
    best_chain = max(atoms_per_chain, key=atoms_per_chain.get)

    coords, resnames = [], set()
    for key, xyzs in qualifying.items():
        if key[1] != best_chain:
            continue
        coords.extend(xyzs)
        resnames.add(key[0])

    return (np.array(coords) if coords else np.array([])), resnames



def parse_pdbqt_heavy_atoms(text: str) -> list:
    """
    Extract heavy-atom lines from a PDBQT/PDB string.

    Hydrogen detection uses ONLY the atom-name field (cols 12-15).
    We deliberately do NOT check the last-token AD4/Vina type column
    because obabel assigns the type "H" to heavy atoms when it cannot
    perceive bond orders (e.g. raw HETATM lines without CONECT records
    from a crystal PDB), which would incorrectly filter out every heavy
    atom and leave ref=1.

    Standard PDB atom-name rules guarantee that hydrogen atoms always
    have names starting with H (e.g. H, HA, HB1, HD, HS) or with a
    digit followed by H (e.g. 1H, 2HB). Both cases are handled.
    """
    heavy = []
    for line in text.splitlines(keepends=True):
        if not line.startswith(("ATOM", "HETATM")):
            continue
        if len(line) < 17:
            continue
        atom_name = line[12:16].strip().upper() if len(line) > 16 else ""
        # Digit-prefixed names like "1H ", "2HB" are also hydrogens
        is_h = atom_name.startswith("H") or (
            len(atom_name) >= 2 and atom_name[0].isdigit() and atom_name[1] == "H"
        )
        if is_h:
            continue
        heavy.append(line)
    return heavy


def extract_protein_atoms(lines: list) -> np.ndarray:
    """Return Nx3 array of ATOM record coordinates."""
    atoms = []
    for line in lines:
        if line.startswith("ATOM"):
            try:
                atoms.append([float(line[30:38]), float(line[38:46]), float(line[46:54])])
            except ValueError:
                continue
    return np.array(atoms) if atoms else np.array([])


def clean_protein(lines: list, ligand_resnames: set, remove_keys=None) -> list:
    """Keep ATOM records and metal HETATMs; drop water and docked ligand atoms.

    remove_keys=None  -> Automatic: drop every residue whose NAME is in
                         ligand_resnames (original behaviour).
    remove_keys=set() -> Manual: drop only the listed residue INSTANCES
                         (resname, chain, resseq, icode); other HETATM
                         residues (e.g. a cofactor) stay in the receptor.
    """
    out = []
    for line in lines:
        if line.startswith("ATOM"):
            out.append(line)
        elif line.startswith("HETATM"):
            rn = line[17:20].strip()
            if remove_keys is not None:
                if _het_key(line) in remove_keys:
                    continue
                if rn in METAL_IONS or rn not in EXCLUDE_RESNAMES:
                    out.append(line)
                continue
            if rn in METAL_IONS:
                out.append(line)
            elif rn not in ligand_resnames and rn not in EXCLUDE_RESNAMES:
                out.append(line)
    out.append("END\n")
    return out


def round_even(v) -> int:
    return int(np.ceil(v / 2) * 2)


def cap_grid(size: list, max_size: int = 120) -> list:
    return [min(int(s), max_size) for s in size]


def fix_pdbqt_atom_names(pdbqt_path):
    """Truncate atom names longer than 4 characters (MGLTools bug)."""
    fixed = []
    with open(pdbqt_path) as fh:
        for line in fh:
            if line.startswith(("ATOM", "HETATM")):
                name = line[12:16].strip()[:4]
                line = line[:12] + name.ljust(4) + line[16:]
            fixed.append(line)
    with open(pdbqt_path, "w") as fh:
        fh.writelines(fixed)


def strip_receptor_hydrogens(pdbqt_path):
    """
    Remove NONPOLAR hydrogen atoms from a receptor PDBQT, checked by AD4
    atom type (column 77-79), not atom name. MGLTools names many hydrogens
    with digit-prefixed identifiers (e.g. '1HD2', '2HG1') for geminal H's,
    which a name-based "starts with H" check misses entirely — confirmed
    empirically: 100% of H/HD atoms produced by this pipeline use that
    naming convention, so the previous name-based check silently removed
    nothing from any receptor.

    Polar hydrogens (AD4 type 'HD') are explicitly preserved — required for
    Vina's hydrogen-bond donor scoring term.
    """
    kept = []
    with open(pdbqt_path) as fh:
        for line in fh:
            if line.startswith(("ATOM", "HETATM")) and line[77:79].strip() == "H":
                continue  # drop nonpolar H only; keep HD (polar) and all heavy atoms
            kept.append(line)
    with open(pdbqt_path, "w") as fh:
        fh.writelines(kept)



# ──────────────────────────────────────────────────────────────────────────────
# POCKET DETECTION
# ──────────────────────────────────────────────────────────────────────────────

def _run_native_p2rank(pdb_file, p2rank_exec: str, padding: float = 5.0, work_dir=None) -> tuple:
    """Run a native Windows P2Rank launcher and locate its prediction CSVs.

    This is used when a bundled prank.bat/prank.exe is present.  The function
    intentionally searches the generated files instead of assuming one exact
    P2Rank output layout, because P2Rank distributions can differ by version.

    ``work_dir``, when given, is the scratch directory P2Rank is run in
    (e.g. ``grid/<protein_name>/p2rank_run``) so its predictions.csv/
    _points.csv files never land in ``raw_proteins/`` alongside the user's
    input PDBs. Falls back to the PDB's own folder when no ``work_dir`` is
    supplied, preserving old behaviour for any other caller.
    """
    exe = Path(p2rank_exec)
    if not exe.exists():
        raise RuntimeError(f"P2Rank executable not found: {exe}")

    pdb = Path(pdb_file).resolve()
    if work_dir is not None:
        work_dir = Path(work_dir)
        work_dir.mkdir(parents=True, exist_ok=True)
        run_pdb = work_dir / pdb.name
        shutil.copy2(pdb, run_pdb)
        pdb = run_pdb
    else:
        work_dir = pdb.parent
    cmd = [str(exe), "predict", "-f", str(pdb)]
    kwargs = {"stdout": subprocess.PIPE, "stderr": subprocess.PIPE, "text": True, "cwd": str(work_dir)}
    if exe.suffix.lower() in {".bat", ".cmd"}:
        cmd = ["cmd.exe", "/c"] + cmd

    result = subprocess.run(cmd, **kwargs)
    if result.returncode != 0:
        raise RuntimeError(f"P2Rank failed: {(result.stderr or result.stdout).strip()}")

    stem = pdb.stem
    candidates = list(work_dir.rglob(f"{stem}*predictions.csv"))
    if not candidates:
        # Some distributions write into a fixed output directory under the
        # P2Rank installation. Search beside the executable as a second pass.
        candidates = list(exe.parent.rglob(f"{stem}*predictions.csv"))
    if not candidates:
        raise RuntimeError("P2Rank completed but no predictions.csv file was found.")

    pred_file = max(candidates, key=lambda p: p.stat().st_mtime)
    df = pd.read_csv(pred_file)
    df.columns = df.columns.str.strip()
    if df.empty or not {"center_x", "center_y", "center_z"}.issubset(df.columns):
        raise RuntimeError(f"Invalid P2Rank prediction file: {pred_file}")

    best = df.iloc[0]
    center = np.array([best["center_x"], best["center_y"], best["center_z"]], dtype=float)

    size = None
    points = list(pred_file.parent.glob(f"{stem}*_points.csv"))
    if points:
        try:
            pts_df = pd.read_csv(points[0])
            pts_df.columns = pts_df.columns.str.strip()
            if "pocket" in pts_df.columns:
                pts_df = pts_df[pts_df["pocket"] == 1]
            if len(pts_df) >= 4 and {"x", "y", "z"}.issubset(pts_df.columns):
                xyz = pts_df[["x", "y", "z"]].values.astype(float)
                extent = xyz.max(axis=0) - xyz.min(axis=0)
                size = cap_grid([round_even(v) for v in (extent + 2 * padding)])
        except Exception:
            size = None

    if size is None:
        size = cap_grid([round_even(v) for v in (np.array([12.0, 12.0, 12.0]) + 2 * padding)])

    return center, size


def run_p2rank(pdb_file, p2rank_exec: str, padding: float = 5.0, work_dir=None) -> tuple:
    """Run the bundled native Windows P2Rank executable."""
    if not p2rank_exec or not str(p2rank_exec).strip():
        raise RuntimeError("P2Rank path is not configured.")

        raise RuntimeError(
            "Please use the bundled native P2Rank tool."
        )

    return _run_native_p2rank(pdb_file, p2rank_exec, padding, work_dir=work_dir)


def run_fpocket(pdb_file, fpocket_exec: str, work_dir=None):
    """Run the bundled native Windows fpocket executable.

    ``work_dir``, when given, is the scratch directory fpocket is run in
    (e.g. ``grid/<protein_name>/fpocket_run``) so its output never lands in
    ``raw_proteins/`` alongside the user's input PDBs. Falls back to the
    PDB's own folder when no ``work_dir`` is supplied, preserving old
    behaviour for any other caller.
    """
    pdb_file = Path(pdb_file)

    if not pdb_file.exists():
        raise RuntimeError(f"fpocket input PDB not found: {pdb_file}")

    fpocket_exec = str(fpocket_exec or "").strip()
    if not fpocket_exec:
        raise RuntimeError("Native fpocket executable is not configured.")

        raise RuntimeError(
            "Please use the bundled native fpocket.exe."
        )

    exe = Path(fpocket_exec)
    if not exe.exists():
        raise RuntimeError(f"fpocket executable not found: {exe}")

    if work_dir is not None:
        # Always run in a dedicated scratch dir (kept with the grid config,
        # not the raw input folder) and always work on a copy of the PDB,
        # so a locked/stale previous run never blocks this one and
        # raw_proteins/ stays input-only.
        run_dir = Path(work_dir)
        run_dir.mkdir(parents=True, exist_ok=True)
        run_pdb = run_dir / pdb_file.name
        shutil.copy2(pdb_file, run_pdb)
        out_dir = run_dir / f"{pdb_file.stem}_out"
        if out_dir.exists():
            try:
                shutil.rmtree(out_dir)
            except (PermissionError, OSError):
                unique_tag = f"{os.getpid()}_{int(time.time() * 1000)}"
                run_dir = run_dir / f".fpocket_{unique_tag}"
                run_dir.mkdir(parents=True, exist_ok=False)
                run_pdb = run_dir / pdb_file.name
                shutil.copy2(pdb_file, run_pdb)
                out_dir = run_dir / f"{pdb_file.stem}_out"
    else:
        out_dir = pdb_file.parent / f"{pdb_file.stem}_out"
        run_dir = pdb_file.parent
        run_pdb = pdb_file

        # fpocket always creates "<input_stem>_out". On Windows, an older
        # fpocket output can be locked by Explorer, a viewer, antivirus, or
        # another process. Do not fail the entire pocket-detection method just
        # because that previous directory cannot be removed. Instead, run fpocket
        # in a unique temporary working directory using a copy of the PDB.
        if out_dir.exists():
            try:
                shutil.rmtree(out_dir)
            except (PermissionError, OSError):
                unique_tag = f"{os.getpid()}_{int(time.time() * 1000)}"
                run_dir = pdb_file.parent / f".{pdb_file.stem}_fpocket_{unique_tag}"
                run_dir.mkdir(parents=True, exist_ok=False)
                run_pdb = run_dir / pdb_file.name
                shutil.copy2(pdb_file, run_pdb)
                out_dir = run_dir / f"{pdb_file.stem}_out"

    result = subprocess.run(
        [str(exe), "-f", run_pdb.name],
        cwd=str(run_dir),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        errors="replace",
    )

    if result.returncode != 0:
        error_text = (
            result.stderr.strip()
            or result.stdout.strip()
            or "unknown fpocket error"
        )
        raise RuntimeError(f"fpocket failed: {error_text}")

    pocket_file = out_dir / "pockets" / "pocket1_atm.pdb"
    if not pocket_file.exists():
        raise RuntimeError(
            f"fpocket completed but pocket file was not found: {pocket_file}"
        )

    return out_dir


def get_fpocket_center_and_size(pocket_file, padding: float = 5.0) -> tuple:
    """Parse an fpocket pocket atom file and return (center, size).

    fpocket writes pocket1_atm.pdb containing the residue atoms lining the
    cavity.  The geometric extent of those atoms is a real measurement of the
    binding site — far more accurate than a hardcoded 26 Å constant.

    Returns:
        (center, size) — both lists/arrays of 3 Angstrom values.
    """
    coords = []
    with open(pocket_file) as fh:
        for line in fh:
            if line.startswith(("HETATM", "ATOM")):
                try:
                    coords.append([float(line[30:38]), float(line[38:46]), float(line[46:54])])
                except ValueError:
                    continue
    if not coords:
        raise RuntimeError(f"No atoms in fpocket file: {pocket_file}")
    arr    = np.array(coords)
    center = arr.mean(axis=0)
    extent = arr.max(axis=0) - arr.min(axis=0)
    size   = cap_grid([round_even(v) for v in (extent + 2 * padding)])
    return center, size


# ──────────────────────────────────────────────────────────────────────────────
# VINA DOCKING
# ──────────────────────────────────────────────────────────────────────────────

def run_single_docking(job: tuple):
    """
    Run one AutoDock Vina job.
    job = (receptor, ligand, config_file, vina_exe,
           exhaustiveness, num_modes, energy_range, cores, dock_dir, result_dir, seed)
    Returns ("success"|"failed", protein_name, ligand_name, message).
    """
    rec, lig, config_file, vina_exe, exhaustiveness, num_modes, \
        energy_range, cores_per_job, dock_dir, result_dir, seed = job

    protein_name = Path(rec).stem.replace("_receptor", "")
    ligand_name  = Path(lig).stem
    out_pdbqt    = dock_dir   / f"{protein_name}_{ligand_name}.pdbqt"
    log_txt      = result_dir / f"{protein_name}_{ligand_name}.txt"

    try:
        cmd = [
            str(vina_exe),
            "--receptor",      str(rec),
            "--ligand",        str(lig),
            "--config",        str(config_file),
            "--exhaustiveness",str(exhaustiveness),
            "--num_modes",     str(num_modes),
            "--energy_range",  str(energy_range),
            "--cpu",           str(cores_per_job),
            "--out",           str(out_pdbqt),
        ]
        # Fixed seed => reproducible results run-to-run (Vina otherwise seeds
        # from system entropy, so re-running the same job gives different
        # poses each time — important for a validation study others need to
        # be able to reproduce).
        if seed is not None:
            cmd += ["--seed", str(seed)]

        result = subprocess.run(
            cmd,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            text=True, shell=False,
        )
        if result.returncode != 0:
            return ("failed", protein_name, ligand_name, result.stderr.strip())

        log_txt.write_text(result.stdout)

        if not out_pdbqt.exists() or out_pdbqt.stat().st_size == 0:
            return ("failed", protein_name, ligand_name, "Empty output file")

        return ("success", protein_name, ligand_name, "")

    except Exception as exc:
        return ("failed", protein_name, ligand_name, str(exc))



def parse_vina_log(log_file) -> float | None:
    """Extract best affinity (mode 1) from a Vina log file."""
    import re
    try:
        with open(log_file) as fh:
            for line in fh:
                m = re.match(r'^\s*1\s+(-?\d+\.\d+)', line)
                if m:
                    return float(m.group(1))
    except Exception:
        pass
    return None


def parse_vina_all_modes(log_file) -> list:
    """Return list of (mode_number, affinity) from a Vina log."""
    import re
    modes = []
    try:
        with open(log_file) as fh:
            for line in fh:
                m = re.match(r'^\s*(\d+)\s+(-?\d+\.\d+)\s+\S+\s+\S+', line)
                if m:
                    modes.append((int(m.group(1)), float(m.group(2))))
    except Exception:
        pass
    return sorted(modes, key=lambda x: x[0])


# ──────────────────────────────────────────────────────────────────────────────
# POSE EXTRACTION & RMSD
# ──────────────────────────────────────────────────────────────────────────────

def pdbqt_to_pdb_text(pdbqt_path, first_pose_only: bool = True) -> str:
    """
    Convert a PDBQT file to plain PDB text for 3D viewing.
    If first_pose_only, returns only the first MODEL block.
    """
    lines = Path(pdbqt_path).read_text(errors="replace").splitlines(keepends=True)
    has_models = any(l.startswith("MODEL") for l in lines)

    if not has_models:
        return "".join(l for l in lines if l.startswith(("ATOM", "HETATM", "END")))

    out, in_model, model_count = [], False, 0
    for line in lines:
        if line.startswith("MODEL"):
            model_count += 1
            if first_pose_only and model_count > 1:
                break
            in_model = True
            out.append(line)
        elif line.startswith("ENDMDL"):
            out.append(line)
            in_model = False
        elif in_model:
            out.append(line)
    return "".join(out)


def pdbqt_to_sdf_text(pdbqt_path, obabel_path: str, first_pose_only: bool = True, add_hydrogens: bool = True) -> str:
    """
    Convert a PDBQT ligand pose to SDF format using Open Babel.
    SDF preserves explicit bond tables (bond orders, ring perception),
    which py3Dmol needs to render complex ligands correctly.
    Falls back to empty string on failure (caller should use PDB fallback).
    """
    import tempfile
    pdbqt_path = str(pdbqt_path)

    # If we only want the first pose, write a temp PDBQT with just MODEL 1
    if first_pose_only:
        lines = Path(pdbqt_path).read_text(errors="replace").splitlines(keepends=True)
        has_models = any(l.startswith("MODEL") for l in lines)
        if has_models:
            first_block, in_model, done = [], False, False
            for line in lines:
                if done:
                    break
                if line.startswith("MODEL"):
                    in_model = True
                    first_block.append(line)
                elif line.startswith("ENDMDL"):
                    first_block.append(line)
                    done = True
                elif in_model:
                    first_block.append(line)
            tmp_pdbqt = tempfile.NamedTemporaryFile(suffix=".pdbqt", delete=False, mode="w")
            tmp_pdbqt.writelines(first_block)
            tmp_pdbqt.flush()
            tmp_pdbqt.close()
            pdbqt_path = tmp_pdbqt.name

    try:
        tmp_sdf = tempfile.NamedTemporaryFile(suffix=".sdf", delete=False)
        tmp_sdf.close()
        obabel_cmd = [obabel_path, pdbqt_path, "-O", tmp_sdf.name]
        if add_hydrogens:
            obabel_cmd.append("-h")

        result = subprocess.run(
            obabel_cmd,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=30,
            env=_obabel_env(obabel_path),
        )
        if result.returncode == 0 and Path(tmp_sdf.name).exists():
            sdf_content = Path(tmp_sdf.name).read_text(errors="replace")
            if sdf_content.strip():
                return sdf_content
        return ""
    except Exception:
        return ""
    finally:
        try:
            import os
            os.unlink(tmp_sdf.name)
        except Exception:
            pass
        if first_pose_only:
            try:
                import os
                os.unlink(pdbqt_path)
            except Exception:
                pass


def split_multi_pose_text(text: str, fmt: str) -> list:
    """Split a multi-pose ligand text block (produced with
    ``first_pose_only=False``) into a list of single-pose text blocks, one
    per Vina mode -- so each can be loaded as its own 3Dmol model instead of
    only the first pose ever being visible (3Dmol's ``addModel`` only ever
    renders the first molecule/frame of a multi-model string; see
    https://github.com/3dmol/3Dmol.js/issues/239). Returns [] if there's
    only one pose (nothing extra to add on top of the primary model).
    """
    if not text or not text.strip():
        return []

    if fmt == "sdf":
        parts = [p.strip("\n") for p in text.split("$$$$")]
        blocks = [p + "\n$$$$\n" for p in parts if p.strip()]
    else:  # pdb, grouped by MODEL...ENDMDL
        blocks, current = [], []
        for line in text.splitlines(keepends=True):
            current.append(line)
            if line.startswith("ENDMDL"):
                blocks.append("".join(current))
                current = []
        if current and any(l.startswith(("ATOM", "HETATM")) for l in current):
            blocks.append("".join(current))

    return blocks[1:]  # first pose is already rendered as the primary model


def extract_vina_pose_by_mode(pdbqt_path: str, mode_number: int) -> list:
    """Return ATOM/HETATM lines for a specific Vina mode."""
    lines = Path(pdbqt_path).read_text(errors="replace").splitlines(keepends=True)
    current_model, in_target, coords = 0, False, []
    for line in lines:
        if line.startswith("MODEL"):
            try:
                current_model = int(line.split()[1])
            except (IndexError, ValueError):
                current_model += 1
            in_target = (current_model == mode_number)
        elif line.startswith("ENDMDL"):
            if in_target:
                break
            in_target = False
        elif in_target and line.startswith(("ATOM", "HETATM")):
            coords.append(line)
    if not coords and mode_number == 1:
        coords = [l for l in lines if l.startswith(("ATOM", "HETATM"))]
    return coords


def _count_pdbqt_models(pdbqt_path) -> int:
    """
    Count how many Vina pose (MODEL) blocks a docked PDBQT contains, so the
    best-pose RMSD sweep below knows how many modes to try. Falls back to 1
    for older/single-pose PDBQTs with no MODEL records at all.
    """
    import re
    try:
        text = Path(pdbqt_path).read_text(errors="replace")
    except Exception:
        return 0
    n = len(re.findall(r"^MODEL\s+\d+", text, flags=re.MULTILINE))
    if n > 0:
        return n
    return 1 if ("ATOM" in text or "HETATM" in text) else 0


def _is_hydrogen(line: str) -> bool:
    """
    Return True if a PDBQT/PDB ATOM/HETATM line represents a hydrogen.

    Uses ONLY the atom-name field (cols 12-15). The AD4/Vina type column
    (last token) is NOT used because obabel assigns type "H" to heavy atoms
    when bond perception fails on CONECT-less crystal PDB files, which would
    cause every heavy atom in the reference to be filtered out (ref=1 bug).

    Covers standard naming conventions:
      - Names starting with H:  H, HA, HB, HD, HS, HZ ...
      - Digit-prefixed H names: 1H, 2HB, 3HG ... (old PDB convention)
    """
    if len(line) < 17:
        return False
    atom_name = line[12:16].strip().upper()
    return atom_name.startswith("H") or (
        len(atom_name) >= 2 and atom_name[0].isdigit() and atom_name[1] == "H"
    )


def _coordinate_bridge_rmsd(ref_heavy_lines: list, pose_heavy_lines: list,
                             lig_stem: str, prep_lig_dir,
                             ref_sdf_text: str = "",
                             tolerance: float = 0.02,
                             max_automorphisms: int = 2000):
    """
    Best-case RMSD path: establishes the reference<->docked-pose atom
    correspondence via EXACT coordinate identity through the ligand
    preparation pipeline's own provenance, instead of via bond-graph
    matching or spatial nearest-neighbor guessing.

    Why this can succeed where compute_rmsd_from_sdf()'s graph-based
    stages cannot: AutoDock Vina never reorders, adds, or removes atoms
    in a docked pose PDBQT relative to the PRE-DOCKING prepared ligand
    PDBQT it was given -- it only rotates/translates them. And
    MGLTools' torsion-tree reordering from the (optionally protonated)
    input structure into that prepared PDBQT is itself just a
    reordering of the SAME 3D coordinates, not a recomputation of them.
    So whenever the uploaded reference has the same coordinates as
    whatever originally went into ligand prep for this ligand (true
    whenever the reference is the same co-crystallised structure used
    to build raw_ligands/{lig_stem}, not a separately regenerated one),
    we can chain:
        reference atom -[exact coordinate match]-> prepared PDBQT row
                        -[same row, Vina invariant]-> docked pose row
    with no bond-perception step, and no assumption that the pose is
    spatially close to the reference. That second point is what makes
    this succeed on cases the graph/spatial fallbacks in
    compute_rmsd_from_sdf() cannot: a rotatable substituent that moved
    far from its reference position during docking still has a fixed,
    correct correspondence here, because the correspondence was never
    spatial to begin with -- it was fixed by ligand-prep bookkeeping
    before docking happened.

    SYMMETRY REFINEMENT (second layer): the coordinate bridge fixes
    atom IDENTITY (this is atom 5 in both files), but says nothing
    about molecular SYMMETRY -- if the ligand has a locally symmetric
    group (a phenyl ring, a carboxylate, a tert-butyl), that group can
    flip into a chemically-indistinguishable orientation during docking
    without the pose being "wrong". The bridge alone would score that
    flip as a large per-atom displacement, even though a symmetry-
    equivalent relabelling of the SAME correspondence gives a much
    smaller, chemically honest RMSD. This refinement computes the
    reference ligand's own automorphism group (from ref_sdf_text, a
    cleanly-bonded source -- NOT the pose's PDBQT-derived bonds, which
    is exactly the unreliable input the bridge was built to avoid) and
    minimizes RMSD over that group, on top of the bridge's fixed
    identity mapping. This never changes WHICH atoms correspond, only
    which chemically-equivalent labelling of that correspondence is
    scored. If ref_sdf_text is unavailable, doesn't parse, or its
    heavy-atom order doesn't line up element-for-element with
    ref_heavy_lines, this refinement is silently skipped and the plain
    bridge RMSD is returned unchanged -- it is a strict enhancement,
    never a requirement.

    Returns (rmsd, note) on success. Returns None if the bridge does
    not apply (no prepared-ligand PDBQT retained for this ligand, atom
    counts don't match, or some reference atom has no unambiguous exact
    coordinate match) -- callers should fall back to
    compute_rmsd_from_sdf() in that case; nothing here is a substitute
    for it, only a preferred first attempt.
    """
    prep_pdbqt = Path(prep_lig_dir) / f"{lig_stem}.pdbqt"
    if not prep_pdbqt.exists():
        return None

    _TWO_LETTER_ELEMENTS = {
        "CL", "BR", "NA", "MG", "CA", "ZN", "FE", "MN", "CU", "SE", "SI", "AL",
    }

    def _element_from_name(name: str) -> str:
        """
        Derive an element symbol from a PDB/PDBQT atom-name field (cols
        12-16). Used instead of trusting the trailing columns, because
        PDBQT replaces the standard PDB element column with charge +
        AutoDock atom type (e.g. "0.266  A", "-0.219 NA") -- reading
        that as an element is wrong, not just imprecise. Handles a
        leading digit (old-style "1HB" hydrogen naming) and a short
        list of common two-letter elements; anything else falls back
        to the first alphabetic character, which is exactly what
        _is_hydrogen() already relies on for H-detection.
        """
        s = name.strip().upper()
        if s and s[0].isdigit():
            s = s[1:]
        if len(s) >= 2 and s[:2] in _TWO_LETTER_ELEMENTS:
            return s[:2]
        return s[:1]

    def _parse_heavy(lines):
        out = []
        for line in lines:
            if not line.startswith(("ATOM", "HETATM")) or _is_hydrogen(line):
                continue
            elem = _element_from_name(line[12:16])
            try:
                x, y, z = float(line[30:38]), float(line[38:46]), float(line[46:54])
            except ValueError:
                continue
            out.append((elem, x, y, z))
        return out

    try:
        prep_lines = prep_pdbqt.read_text(errors="replace").splitlines(keepends=True)
    except Exception:
        return None

    prep_heavy = _parse_heavy(prep_lines)
    ref_heavy = _parse_heavy(ref_heavy_lines)
    pose_heavy = _parse_heavy(pose_heavy_lines)

    if not prep_heavy or len(prep_heavy) != len(pose_heavy):
        # Not the pose that came from this prepared ligand -- filename
        # matching upstream should prevent this, but never silently
        # mismap if it happens anyway.
        return None

    if len(ref_heavy) != len(prep_heavy):
        return None

    # ref_row -> prep_row via exact (tolerance-gated) coordinate match.
    # Each prep atom is consumed at most once.
    used = set()
    ref_to_prep = {}
    for ri, (relem, rx, ry, rz) in enumerate(ref_heavy):
        best_j, best_d = None, None
        for j, (pelem, px, py, pz) in enumerate(prep_heavy):
            if j in used or pelem != relem:
                continue
            d = ((rx - px) ** 2 + (ry - py) ** 2 + (rz - pz) ** 2) ** 0.5
            if d <= tolerance and (best_d is None or d < best_d):
                best_j, best_d = j, d
        if best_j is None:
            return None
        used.add(best_j)
        ref_to_prep[ri] = best_j

    # Compose ref_row -> prep_row -> pose_row (same row index in the
    # docked pose as in the prepared ligand -- the Vina invariant).
    n = len(ref_to_prep)

    def _rmsd_for_mapping(idx_map):
        """RMSD for a given ref_row -> pose_row correspondence (a dict
        or list indexable by ref row)."""
        total = 0.0
        for ri in range(n):
            relem, rx, ry, rz = ref_heavy[ri]
            pose_row = idx_map[ri]
            pelem, px, py, pz = pose_heavy[pose_row]
            if pelem != relem:
                return None  # sanity check: element must still agree
            total += (rx - px) ** 2 + (ry - py) ** 2 + (rz - pz) ** 2
        return round((total / n) ** 0.5, 4)

    base_rmsd = _rmsd_for_mapping(ref_to_prep)
    if base_rmsd is None:
        return None  # sanity check: element must still agree at this row

    # -----------------------------------------------------------------
    # Symmetry refinement (optional second layer, see docstring). Never
    # changes WHICH atoms correspond -- only searches for a chemically
    # equivalent relabelling of that same correspondence that scores a
    # lower, more honest RMSD when the ligand has genuine local
    # symmetry (e.g. a flipped phenyl ring or carboxylate).
    # -----------------------------------------------------------------
    best_rmsd = base_rmsd
    symmetry_note = ""

    if ref_sdf_text and ref_sdf_text.strip():
        try:
            ref_mol = _Chem.MolFromMolBlock(ref_sdf_text, removeHs=False, sanitize=True)
            if ref_mol is not None:
                h_idx = [a.GetIdx() for a in ref_mol.GetAtoms() if a.GetAtomicNum() == 1]
                if h_idx:
                    rw = _Chem.RWMol(ref_mol)
                    for idx in sorted(h_idx, reverse=True):
                        rw.RemoveAtom(idx)  # descending order preserves relative order of the rest
                    ref_mol = rw.GetMol()

                # Sanity check: heavy-atom element sequence must line up
                # 1:1 with ref_heavy before any automorphism is trusted --
                # if Open Babel's SDF conversion reordered atoms relative
                # to the raw reference lines, automorphism indices would
                # silently refer to the wrong atoms.
                mol_elems = [a.GetSymbol().upper() for a in ref_mol.GetAtoms()]
                line_elems = [e.upper() for (e, _, _, _) in ref_heavy]
                if len(mol_elems) == len(line_elems) and mol_elems == line_elems:
                    matches = ref_mol.GetSubstructMatches(
                        ref_mol, uniquify=False, useChirality=True,
                        maxMatches=max_automorphisms,
                    )
                    n_automorphisms = len(matches)
                    for sigma in matches:
                        if len(sigma) != n:
                            continue
                        # sigma(i) is the ref atom equivalent to atom i;
                        # score that relabelling against the bridge's
                        # already-fixed identity mapping.
                        relabelled_map = [ref_to_prep[sigma[i]] for i in range(n)]
                        cand = _rmsd_for_mapping(relabelled_map)
                        if cand is not None and cand < best_rmsd:
                            best_rmsd = cand
                    if n_automorphisms > 1 and best_rmsd < base_rmsd:
                        symmetry_note = (
                            f" A {n_automorphisms}-fold local symmetry in the "
                            "reference was found and used to refine the score "
                            f"(unrefined bridge RMSD was {base_rmsd} \u00c5)."
                        )
        except Exception:
            pass  # symmetry refinement is optional -- fall through to base_rmsd

    return best_rmsd, (
        "Exact atom correspondence via ligand-preparation provenance "
        "(reference matched to the pre-docking prepared ligand PDBQT by "
        "coordinate identity; Vina preserves atom order from that file "
        "into every docked pose) \u2014 no bond-graph matching or spatial "
        "correspondence guessing was needed or used." + symmetry_note
    )


def pdb_to_sdf_text(pdb_text: str, obabel_path: str) -> str:
    """
    Convert a reference ligand PDB (text) to SDF using Open Babel, the same
    way pdbqt_to_sdf_text() already does for docked poses. This is what
    makes redocking RMSD naming-agnostic: both molecules end up as SDF
    graphs with bond tables, and compute_rmsd_from_sdf() matches them by
    graph structure, not by atom name — which matters because ligands
    prepared from SDF/MOL2 (see the screening pipeline above) get
    Open-Babel-generated PDB-style atom names that will not, in general,
    match the RCSB chemical-component-dictionary names on a reference
    ligand downloaded straight from the PDB.
    """
    import tempfile
    tmp_pdb = tmp_sdf = None
    try:
        tmp_pdb = tempfile.NamedTemporaryFile(suffix=".pdb", delete=False, mode="w")
        tmp_pdb.write(pdb_text)
        tmp_pdb.flush()
        tmp_pdb.close()
        tmp_sdf = tempfile.NamedTemporaryFile(suffix=".sdf", delete=False)
        tmp_sdf.close()
        result = subprocess.run(
            [obabel_path, tmp_pdb.name, "-O", tmp_sdf.name],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=30,
            env=_obabel_env(obabel_path),
        )
        if result.returncode == 0 and Path(tmp_sdf.name).exists():
            sdf_content = Path(tmp_sdf.name).read_text(errors="replace")
            if sdf_content.strip():
                return sdf_content
        return ""
    except Exception:
        return ""
    finally:
        for tmp in (tmp_pdb, tmp_sdf):
            try:
                if tmp:
                    os.unlink(tmp.name)
            except Exception:
                pass


def extract_vina_pose_by_mode(pdbqt_path: str, mode_number: int) -> list:
    """Return ATOM/HETATM lines for a specific Vina mode."""
    lines = Path(pdbqt_path).read_text(errors="replace").splitlines(keepends=True)
    current_model, in_target, coords = 0, False, []
    for line in lines:
        if line.startswith("MODEL"):
            try:
                current_model = int(line.split()[1])
            except (IndexError, ValueError):
                current_model += 1
            in_target = (current_model == mode_number)
        elif line.startswith("ENDMDL"):
            if in_target:
                break
            in_target = False
        elif in_target and line.startswith(("ATOM", "HETATM")):
            coords.append(line)
    if not coords and mode_number == 1:
        coords = [l for l in lines if l.startswith(("ATOM", "HETATM"))]
    return coords


def compute_rmsd_from_lines(ref_lines: list, pose_lines: list):
    """
    Fast pre-check ONLY: verifies the reference and docked pose plausibly
    have the same number of heavy atoms before we bother invoking Open Babel
    + RDKit. This is NOT the RMSD calculation itself (that's
    compute_rmsd_from_sdf, below) — do not use this function's absence of an
    atom-count error to mean the RMSD is valid.

    Returns (n_ref_heavy, n_pose_heavy, error_string). error_string is None
    if the counts are compatible.
    """
    def _count_heavy(lines):
        n = 0
        for line in lines:
            if not line.startswith(("ATOM", "HETATM")):
                continue
            if _is_hydrogen(line):
                continue
            n += 1
        return n

    n_ref, n_pose = _count_heavy(ref_lines), _count_heavy(pose_lines)
    if n_ref == 0:
        return n_ref, n_pose, "Reference has no heavy atoms"
    if n_pose == 0:
        return n_ref, n_pose, "Pose has no heavy atoms"
    if n_ref != n_pose:
        return n_ref, n_pose, f"Atom count mismatch: ref={n_ref}, pose={n_pose}"
    return n_ref, n_pose, None


def compute_rmsd_from_sdf(ref_sdf_text: str, pose_sdf_text: str):
    """
    Two-stage redocking RMSD validation.

    Stage 1: sPyRMSD symmetry-aware graph matching on the reference and
             docked pose exactly as independently parsed.
    Stage 2: a cheap RDKit sanitize/normalize pass on both molecules,
             then sPyRMSD again — this fixes cases where the raw parse
             just wasn't sanitized correctly (valence/aromaticity
             flags), not genuine connectivity differences.
    No RMSD is returned if neither stage produces a valid graph-
    isomorphism correspondence. Cases where bond perception itself
    disagrees between reference and pose (not just sanitization) are
    reported as failures rather than resolved via spatial atom
    correspondence, since a nearest-atom mapping doesn't guarantee the
    atoms are chemically the same one — only graph-verified
    correspondences are used to compute RMSD.

    RMSD is heavy-atom RMSD in the original receptor coordinate frame.
    No translation/rotation minimization is applied.
    """
    if not _RMSD_DEPS_OK:
        return None, (
            "Validation RMSD dependencies are unavailable. "
            f"Import error: {_RMSD_DEPS_ERROR}"
        ), None

    def _strip_h(mol):
        h_idx = [
            a.GetIdx() for a in mol.GetAtoms()
            if a.GetAtomicNum() == 1
        ]
        if not h_idx:
            return mol
        rw = _Chem.RWMol(mol)
        for idx in sorted(h_idx, reverse=True):
            rw.RemoveAtom(idx)
        return rw.GetMol()

    def _extract_pdbqt_model(text, model_number=1):
        """
        Extract a single MODEL from a multi-pose PDBQT file.

        AutoDock Vina writes multiple docking poses as MODEL blocks.
        Validation must compare the reference ligand against one
        individual pose, not the concatenated coordinates of all poses.
        """
        if not text:
            return text

        lines = text.splitlines()

        has_models = any(
            line.startswith("MODEL")
            for line in lines
        )

        if not has_models:
            return text

        selected = []
        inside = False

        for line in lines:
            if line.startswith("MODEL"):
                parts = line.split()

                try:
                    number = int(parts[1])
                except Exception:
                    number = None

                inside = (number == model_number)

                if inside:
                    selected.append(line)

                continue

            if line.startswith("ENDMDL"):
                if inside:
                    selected.append(line)
                inside = False
                continue

            if inside:
                selected.append(line)

        if not selected:
            return None

        return "\n".join(selected) + "\n"


    def _parse(text, sanitize=True):
        # PDBQT docking output may contain multiple Vina poses.
        # Keep only MODEL 1 for validation.
        extracted = _extract_pdbqt_model(text, model_number=1)

        if extracted is None:
            return None

        # MolBlock parsing is retained for SDF/MolBlock input.
        mol = _Chem.MolFromMolBlock(
            extracted,
            removeHs=True,
            sanitize=sanitize
        )

        if mol is None and sanitize:
            mol = _Chem.MolFromMolBlock(
                text,
                removeHs=False,
                sanitize=False
            )
            if mol is not None:
                try:
                    _Chem.SanitizeMol(
                        mol,
                        sanitizeOps=(
                            _Chem.SANITIZE_ALL
                            ^ _Chem.SANITIZE_PROPERTIES
                        )
                    )
                except Exception:
                    pass

        if mol is None:
            return None

        return _strip_h(mol)

    def _spyrmsd(ref_mol, pose_mol):
        r = _spymol.Molecule.from_rdkit(ref_mol)
        q = _spymol.Molecule.from_rdkit(pose_mol)

        r.strip()
        q.strip()

        result = _spyrmsd_rmsd.symmrmsd(
            r.coordinates,
            q.coordinates,
            r.atomicnums,
            q.atomicnums,
            r.adjacency_matrix,
            q.adjacency_matrix,
            center=False,
            minimize=False,
        )

        value = (
            float(result[0])
            if isinstance(result, (list, tuple, np.ndarray))
            else float(result)
        )

        return round(value, 4)

    def _normalize_bonds(mol):
        """
        Rebuild a sanitized copy where possible. This is deliberately
        conservative: connectivity is preserved and no arbitrary bonds
        are created.
        """
        cp = _Chem.Mol(mol)

        try:
            _Chem.SanitizeMol(cp)
        except Exception:
            try:
                _Chem.SanitizeMol(
                    cp,
                    sanitizeOps=(
                        _Chem.SANITIZE_ALL
                        ^ _Chem.SANITIZE_PROPERTIES
                    )
                )
            except Exception:
                pass

        return _strip_h(cp)

    ref = _parse(ref_sdf_text)
    pose = _parse(pose_sdf_text)

    if ref is None:
        return None, "Could not parse reference ligand with RDKit.", None

    if pose is None:
        return None, "Could not parse docked pose with RDKit.", None

    n_ref = ref.GetNumAtoms()
    n_pose = pose.GetNumAtoms()

    if n_ref == 0:
        return None, "Reference ligand contains no heavy atoms.", None

    if n_pose == 0:
        return None, "Docked pose contains no heavy atoms.", None

    if n_ref != n_pose:
        return None, (
            f"Heavy-atom count mismatch: reference={n_ref}, "
            f"pose={n_pose}. Re-docking RMSD requires the same ligand."
        ), None

    debug = []  # human-readable per-stage diagnostics, surfaced on total failure

    # ---------------------------------------------------------------
    # STAGE 1 - primary sPyRMSD symmetry-aware graph matching
    # ---------------------------------------------------------------
    try:
        value = _spyrmsd(ref, pose)

        return (
            value,
            None,
            "sPyRMSD symmetry-corrected graph matching "
            "(primary validation)"
        )

    except Exception as exc1:
        debug.append(f"stage1 (sPyRMSD, raw): {exc1}")

    # ---------------------------------------------------------------
    # STAGE 2 - bond-graph repair + sPyRMSD
    # ---------------------------------------------------------------
    # RDKit sanitize/normalize (cheap, unchanged from before) — fixes
    # cases where the raw parse just wasn't sanitized correctly
    # (valence/aromaticity flags), not genuine connectivity
    # differences. If the reference's and the pose's independently
    # perceived bond graphs are still not isomorphic after this, that
    # is treated as a genuine failure rather than papered over with a
    # spatial (non-graph-verified) atom correspondence.
    # ---------------------------------------------------------------
    try:
        ref_norm = _normalize_bonds(ref)
        pose_norm = _normalize_bonds(pose)

        value = _spyrmsd(ref_norm, pose_norm)

        return (
            value,
            None,
            "sPyRMSD symmetry-corrected graph matching "
            "(after RDKit graph normalization)"
        )

    except Exception as exc2a:
        debug.append(f"stage2a (sPyRMSD, normalized): {exc2a}")

    return None, (
        "No atom correspondence could be established after sPyRMSD "
        "(raw) or RDKit graph normalization. RMSD was not "
        "calculated. Per-stage diagnostics: " + " | ".join(debug)
    ), "NO RMSD"


# ──────────────────────────────────────────────────────────────────────────────
# BINDING-SITE CONTACT ANALYSIS
# (geometric, distance-based residue/interaction mapping for the pose viewer
#  and for figure/caption generation -- same spirit as Schrodinger's ligand
#  interaction diagram, built without any external interaction-analysis
#  dependency. This is a HEURISTIC: distance-only, no donor/acceptor angle
#  geometry, no salt-bridge/pi-cation detection. Treat flagged interactions
#  as candidates for a figure, not as a validated substitute for a tool like
#  PLIP if the manuscript needs a rigorously defined interaction footprint.)
# ──────────────────────────────────────────────────────────────────────────────

# Side-chain atoms capable of acting as H-bond donors / acceptors, by residue.
# Backbone N (donor) and O (acceptor) apply to every residue and are added
# automatically in compute_ligand_contacts().
_AA_DONOR_ATOMS = {
    "SER": {"OG"}, "THR": {"OG1"}, "TYR": {"OH"}, "CYS": {"SG"},
    "HIS": {"ND1", "NE2"}, "TRP": {"NE1"}, "LYS": {"NZ"},
    "ARG": {"NE", "NH1", "NH2"}, "ASN": {"ND2"}, "GLN": {"NE2"},
}
_AA_ACCEPTOR_ATOMS = {
    "SER": {"OG"}, "THR": {"OG1"}, "TYR": {"OH"},
    "ASP": {"OD1", "OD2"}, "GLU": {"OE1", "OE2"},
    "ASN": {"OD1"}, "GLN": {"OE1"},
    "HIS": {"ND1", "NE2"}, "MET": {"SD"}, "CYS": {"SG"},
}
_HYDROPHOBIC_RES = {"ALA", "VAL", "LEU", "ILE", "MET", "PHE", "TRP", "PRO", "CYS"}
# Ring atoms used for aromatic-ring centroid (pi-stacking proxy). TRP's
# 6-membered ring only (indole benzo ring) is used for simplicity.
_AROMATIC_RING_ATOMS = {
    "PHE": ["CG", "CD1", "CD2", "CE1", "CE2", "CZ"],
    "TYR": ["CG", "CD1", "CD2", "CE1", "CE2", "CZ"],
    "TRP": ["CD2", "CE2", "CE3", "CZ2", "CZ3", "CH2"],
    "HIS": ["CG", "ND1", "CD2", "CE1", "NE2"],
}
# Side-chain atoms that carry a formal charge at physiological pH, used for
# salt-bridge detection against a formally-charged ligand atom (from RDKit;
# unavailable in the PDB-fallback path, which has no bond/charge info).
# HIS is included as a weak base -- it's often neutral, so a HIS "salt
# bridge" here is a softer call than LYS/ARG and worth a second look.
_AA_BASIC_ATOMS  = {"LYS": {"NZ"}, "ARG": {"NE", "NH1", "NH2"}, "HIS": {"ND1", "NE2"}}
_AA_ACIDIC_ATOMS = {"ASP": {"OD1", "OD2"}, "GLU": {"OE1", "OE2"}}

_CONTACT_COLORS = {
    "H-bond": "#e63946",
    "salt-bridge": "#2a9d8f",
    "hydrophobic": "#f4a300",
    "pi-stacking": "#8338ec",
    "contact": "#adb5bd",
}


def _parse_receptor_pdb_residues(pdb_text: str) -> dict:
    """Parse ATOM records into {(chain, resnum, resname): [atoms]}."""
    residues: dict = {}
    for line in pdb_text.splitlines():
        if not line.startswith("ATOM"):
            continue
        try:
            atom_name = line[12:16].strip()
            resname   = line[17:20].strip()
            chain     = line[21].strip() or "A"
            resnum    = int(line[22:26])
            x = float(line[30:38]); y = float(line[38:46]); z = float(line[46:54])
            element   = (line[76:78].strip() or atom_name[0]).strip().capitalize()
        except (ValueError, IndexError):
            continue
        if atom_name.startswith("H") or element == "H":
            continue
        residues.setdefault((chain, resnum, resname), []).append(
            {"name": atom_name, "element": element, "x": x, "y": y, "z": z}
        )
    return residues


def _ligand_atoms_from_sdf(sdf_text: str):
    """Return (atoms, aromatic_ring_centroids) parsed via RDKit, or None on
    failure. RDKit gives correct bond orders/aromaticity, so donor/acceptor
    and ring perception is far more reliable than a coordinate-only guess."""
    if not _RMSD_DEPS_OK or not sdf_text.strip():
        return None
    try:
        mol = _Chem.MolFromMolBlock(sdf_text, sanitize=True, removeHs=False)
        if mol is None:
            mol = _Chem.MolFromMolBlock(sdf_text, sanitize=False, removeHs=False)
        if mol is None:
            return None
        conf = mol.GetConformer()
        atoms = []
        for atom in mol.GetAtoms():
            if atom.GetSymbol() == "H":
                continue
            idx = atom.GetIdx()
            pos = conf.GetAtomPosition(idx)
            sym = atom.GetSymbol()
            try:
                n_h = atom.GetTotalNumHs()
            except Exception:
                n_h = 0
            try:
                formal_charge = atom.GetFormalCharge()
            except Exception:
                formal_charge = 0
            atoms.append({
                "symbol": sym, "x": pos.x, "y": pos.y, "z": pos.z,
                "is_donor": sym in ("N", "O") and n_h > 0,
                "is_acceptor": sym in ("N", "O", "F"),
                "formal_charge": formal_charge,
            })
        ring_centroids = []
        try:
            ri = mol.GetRingInfo()
            for ring in ri.AtomRings():
                if all(mol.GetAtomWithIdx(i).GetIsAromatic() for i in ring):
                    pts = np.array([[conf.GetAtomPosition(i).x,
                                      conf.GetAtomPosition(i).y,
                                      conf.GetAtomPosition(i).z] for i in ring])
                    ring_centroids.append(pts.mean(axis=0))
        except Exception:
            pass
        return atoms, ring_centroids
    except Exception:
        return None


def _ligand_atoms_from_pdb_fallback(pdb_text: str):
    """Coordinate-only fallback when SDF/RDKit isn't available. Donor/acceptor
    flags are a crude element-based guess (no bond info to check H count).

    Only reads the first MODEL block when the text has multiple poses (e.g.
    the "All poses" ligand text) -- otherwise atoms from every pose would be
    pooled into one contact analysis, which doesn't correspond to any real
    single binding mode.
    """
    atoms = []
    in_model = False
    has_models = "MODEL" in pdb_text
    for line in pdb_text.splitlines():
        if has_models:
            if line.startswith("MODEL"):
                in_model = True
                continue
            if line.startswith("ENDMDL"):
                break
            if not in_model:
                continue
        if not (line.startswith("ATOM") or line.startswith("HETATM")):
            continue
        try:
            atom_name = line[12:16].strip()
            x = float(line[30:38]); y = float(line[38:46]); z = float(line[46:54])
            element = (line[76:78].strip() or atom_name[0]).strip().capitalize()
        except (ValueError, IndexError):
            continue
        if element == "H":
            continue
        atoms.append({
            "symbol": element, "x": x, "y": y, "z": z,
            "is_donor": element in ("N", "O"),
            "is_acceptor": element in ("N", "O"),
        })
    return atoms


def compute_ligand_contacts(receptor_pdb_text: str, ligand_text: str, lig_format: str,
                             pocket_cutoff: float = 4.5, hbond_cutoff: float = 3.5,
                             backbone_hbond_cutoff: float = 3.0,
                             pi_cutoff: float = 5.5,
                             salt_bridge_cutoff: float = 4.0) -> list:
    """Distance-based binding-site contact analysis. Returns one dict per
    contact residue, sorted by closest approach:

        {chain, resnum, resname, residue, min_dist, interaction, detail,
         centroid, hbond_pair}

    interaction is one of "salt-bridge", "H-bond", "pi-stacking",
    "hydrophobic", "contact", chosen by whichever category has the closest
    qualifying atom pair (salt-bridge wins ties against a plain H-bond,
    since a charge-complementary polar contact is the more specific label).

    Backbone N/O is present in EVERY residue, so it is by far the biggest
    source of false-positive "H-bond" calls once a generic distance cutoff
    is applied across an entire pocket (a backbone amide that merely
    happens to pass within range of some ligand heteroatom, with no check
    on whether it's actually oriented to donate/accept, looks identical to
    a real one). Side-chain donor/acceptor atoms (SER-OG, ASN-ND2, etc.)
    are a much more specific signal -- a residue's side chain pointing at
    the ligand is comparatively rare -- so they keep the full hbond_cutoff
    while bare backbone N/O is held to a tighter backbone_hbond_cutoff.
    This does not add real donor-H...acceptor angle geometry (PDB files
    generally lack explicit backbone H coordinates), it just stops treating
    "any backbone atom within 3.5 A" as equally strong evidence as a
    genuine side-chain H-bond.

    Salt-bridge detection needs RDKit-derived formal charges on the ligand
    (the SDF path); the PDB-fallback path has no bond/charge info, so this
    category will simply never fire there. HIS is included as a basic
    residue but is often neutral at physiological pH -- treat a HIS
    salt-bridge call as a softer, worth-checking-manually result.

    hbond_pair (if not None) is {"res":[x,y,z], "lig":[x,y,z]} for drawing
    a dashed line in the viewer -- used for both "H-bond" and "salt-bridge".
    """
    residues = _parse_receptor_pdb_residues(receptor_pdb_text)
    if not residues:
        return []

    parsed = _ligand_atoms_from_sdf(ligand_text) if lig_format == "sdf" else None
    if parsed is not None:
        lig_atoms, lig_ring_centroids = parsed
    else:
        lig_atoms, lig_ring_centroids = _ligand_atoms_from_pdb_fallback(ligand_text), []

    if not lig_atoms:
        return []

    lig_xyz = np.array([[a["x"], a["y"], a["z"]] for a in lig_atoms])

    contacts = []
    for (chain, resnum, resname), atoms in residues.items():
        res_xyz = np.array([[a["x"], a["y"], a["z"]] for a in atoms])
        dmat = np.linalg.norm(res_xyz[:, None, :] - lig_xyz[None, :, :], axis=-1)
        min_dist = float(dmat.min())
        if min_dist > pocket_cutoff:
            continue
        i_res, i_lig = np.unravel_index(np.argmin(dmat), dmat.shape)

        # Find the single BEST (minimum-distance) qualifying pair in each
        # candidate category, then classify by whichever category is
        # actually closest -- not by which category was checked first.
        # (Checking H-bond first and breaking on the first cutoff-satisfying
        # pair let a distant, marginal backbone contact outrank an obviously
        # dominant close hydrophobic contact; this compares real distances.)
        best = {"salt-bridge": (np.inf, None, None), "H-bond": (np.inf, None, None),
                "pi-stacking": (np.inf, None, None), "hydrophobic": (np.inf, None, None)}
        # Tie-break order when two categories land on the identical closest
        # pair (a charge-complementary polar contact satisfies both the
        # generic H-bond search and the salt-bridge search at the same
        # distance) -- prefer the more chemically specific label.
        _priority = {"salt-bridge": 0, "H-bond": 1, "pi-stacking": 2, "hydrophobic": 3}

        donor_names    = {"N"} | _AA_DONOR_ATOMS.get(resname, set())
        acceptor_names = {"O"} | _AA_ACCEPTOR_ATOMS.get(resname, set())
        polar_names    = donor_names | acceptor_names
        sidechain_polar_names = polar_names - {"N", "O"}  # side-chain-specific atoms only
        for ai, ra in enumerate(atoms):
            if ra["name"] not in polar_names:
                continue
            # Backbone N/O gets the tighter cutoff; side-chain donor/acceptor
            # atoms (more specific, less prone to coincidental proximity)
            # keep the full hbond_cutoff.
            this_cutoff = hbond_cutoff if ra["name"] in sidechain_polar_names else backbone_hbond_cutoff
            for aj, la in enumerate(lig_atoms):
                if not (la.get("is_donor") or la.get("is_acceptor")):
                    continue
                d = float(np.linalg.norm(res_xyz[ai] - lig_xyz[aj]))
                if d <= this_cutoff and d < best["H-bond"][0]:
                    best["H-bond"] = (d, ai, aj)

        # --- Salt bridge: basic residue atom + anionic ligand atom, or
        # acidic residue atom + cationic ligand atom. Requires RDKit-derived
        # formal charges on the ligand (SDF path); the PDB-fallback path has
        # no charge info, so every ligand atom reads formal_charge=0 and this
        # search simply finds nothing there -- same limitation as elsewhere.
        basic_names, acidic_names = _AA_BASIC_ATOMS.get(resname), _AA_ACIDIC_ATOMS.get(resname)
        if basic_names or acidic_names:
            for ai, ra in enumerate(atoms):
                if basic_names and ra["name"] in basic_names:
                    want_negative_lig = True
                elif acidic_names and ra["name"] in acidic_names:
                    want_negative_lig = False
                else:
                    continue
                for aj, la in enumerate(lig_atoms):
                    fc = la.get("formal_charge", 0)
                    if want_negative_lig and fc >= 0:
                        continue
                    if not want_negative_lig and fc <= 0:
                        continue
                    d = float(np.linalg.norm(res_xyz[ai] - lig_xyz[aj]))
                    if d <= salt_bridge_cutoff and d < best["salt-bridge"][0]:
                        best["salt-bridge"] = (d, ai, aj)

        if resname in _AROMATIC_RING_ATOMS and lig_ring_centroids:
            ring_names = _AROMATIC_RING_ATOMS[resname]
            ring_pts = np.array([[a["x"], a["y"], a["z"]] for a in atoms if a["name"] in ring_names])
            if len(ring_pts) >= 3:
                res_centroid = ring_pts.mean(axis=0)
                for lc in lig_ring_centroids:
                    d = float(np.linalg.norm(res_centroid - lc))
                    if d <= pi_cutoff and d < best["pi-stacking"][0]:
                        best["pi-stacking"] = (d, res_centroid, lc)

        if resname in _HYDROPHOBIC_RES:
            for ai, ra in enumerate(atoms):
                if ra["element"] != "C":
                    continue
                for aj, la in enumerate(lig_atoms):
                    if la["symbol"] != "C":
                        continue
                    d = float(np.linalg.norm(res_xyz[ai] - lig_xyz[aj]))
                    if d <= 4.5 and d < best["hydrophobic"][0]:
                        best["hydrophobic"] = (d, ai, aj)

        # Pick the category with the smallest qualifying distance; ties
        # (identical closest pair found by two searches) break by _priority.
        interaction = "contact"
        detail = f"{atoms[i_res]['name']} \u2194 nearest ligand atom ({min_dist:.2f} \u00c5)"
        hbond_pair = None
        best_cat, (best_d, ref1, ref2) = min(best.items(), key=lambda kv: (kv[1][0], _priority[kv[0]]))
        if best_d < np.inf:
            interaction = best_cat
            min_dist = min(min_dist, best_d)
            if best_cat in ("H-bond", "salt-bridge"):
                tag = "ionic pair" if best_cat == "salt-bridge" else "lig. atom"
                detail = f"{atoms[ref1]['name']} \u2194 {tag} ({best_d:.2f} \u00c5)"
                hbond_pair = {"res": res_xyz[ref1].tolist(), "lig": lig_xyz[ref2].tolist()}
            elif best_cat == "pi-stacking":
                detail = f"ring centroid \u2194 ring centroid ({best_d:.2f} \u00c5)"
            elif best_cat == "hydrophobic":
                detail = f"{atoms[ref1]['name']} \u2194 lig. C ({best_d:.2f} \u00c5)"

        contacts.append({
            "chain": chain, "resnum": resnum, "resname": resname,
            "residue": f"{resname}{resnum}",
            "min_dist": round(min_dist, 2),
            "interaction": interaction,
            "detail": detail,
            "centroid": res_xyz.mean(axis=0).tolist(),
            "hbond_pair": hbond_pair,
        })

    contacts.sort(key=lambda c: c["min_dist"])
    return contacts


def filter_pdb_to_residues(pdb_text: str, keys: set) -> str:
    """Return only the ATOM lines of pdb_text whose (chain, resnum) is in
    keys, preserving original formatting (used to build the 3D highlight
    layer without reconstructing PDB records by hand)."""
    lines = []
    for line in pdb_text.splitlines():
        if not line.startswith("ATOM"):
            continue
        try:
            chain  = line[21].strip() or "A"
            resnum = int(line[22:26])
        except (ValueError, IndexError):
            continue
        if (chain, resnum) in keys:
            lines.append(line)
    return "\n".join(lines)


# ──────────────────────────────────────────────────────────────────────────────
# 3D VIEWER
# ──────────────────────────────────────────────────────────────────────────────

import html as _html
import re as _re

# Plain (non-f-string) template: tokens of the form __NAME__ are substituted
# by build_viewer_html(). This avoids the {{ }} escaping that an f-string
# would force on ~300 lines of JavaScript.
_VIEWER_TEMPLATE = r"""<!DOCTYPE html><html>
<head>
<meta charset="utf-8">
<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
<script src="https://cdnjs.cloudflare.com/ajax/libs/3Dmol/2.1.0/3Dmol-min.js"></script>
<style>
  * { box-sizing:border-box; margin:0; padding:0; }
  body { background:#f7f7f5; font-family:'Inter',sans-serif; color:#1a1a1a; }
  #viewer { width:100%; height:520px; position:relative; border:1px solid #ddd; border-bottom:none; overflow:hidden; }
  .row { padding:7px 14px; background:#fafafa; border:1px solid #ddd; border-top:none;
         display:flex; gap:9px; flex-wrap:wrap; align-items:center; font-size:12px; }
  #info { padding:7px 14px; background:#f3f3f1; border:1px solid #ddd; border-top:none;
          font-size:11px; color:#555; display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
  #info b { color:#1a4a7a; }
  .lbl { color:#666; font-size:10px; font-weight:600; text-transform:uppercase; letter-spacing:0.06em; white-space:nowrap; }
  select { background:#fff; color:#1a1a1a; border:1px solid #ccc; border-radius:2px;
           padding:3px 6px; font-size:11.5px; font-family:'Inter',sans-serif; cursor:pointer; }
  select:focus { outline:none; border-color:#1a4a7a; }
  button { background:#fff; color:#1a4a7a; border:1px solid #ccc; border-radius:2px;
           padding:4px 11px; cursor:pointer; font-size:11.5px; font-weight:500; transition:all 0.12s; }
  button:hover { background:#e8eef6; border-color:#1a4a7a; }
  button.primary { background:#1a4a7a; color:#fff; border-color:#1a4a7a; }
  button.primary:hover { background:#14385e; }
  label.chk { display:flex; align-items:center; gap:4px; font-size:11px; color:#555; cursor:pointer; }
  .badge { margin-left:auto; font-family:'IBM Plex Mono',monospace; font-size:10.5px; color:#444;
           border:1px solid #ccc; padding:2px 9px; border-radius:2px; background:#fff; white-space:nowrap; }
  .sep { width:1px; height:18px; background:#ddd; }
</style>
</head>
<body>
<div id="viewer"></div>

<div class="row">
  <div class="lbl">Preset</div>
  <select id="preset">
    <option value="publication">Publication (white)</option>
    <option value="interactive">Interactive (dark)</option>
  </select>
  <div class="sep"></div>
  <div class="lbl">Receptor</div>
  <select id="rec_style" class="ctl">
    <option value="cartoon">Cartoon</option><option value="surface">Surface</option>
    <option value="line">Lines</option><option value="stick">Sticks</option>
    <option value="sphere">Spheres</option><option value="hidden">Hidden</option>
  </select>
  <select id="rec_color" class="ctl">
    <option value="pale">Pale blue-grey</option><option value="white">White</option>
    <option value="grey">Grey</option><option value="spectrum">Spectrum</option>
    <option value="chain">By chain</option><option value="ss">Sec. structure</option>
  </select>
  <div class="lbl">Cartoon opacity</div>
  <select id="cart_op" class="ctl">
    <option value="1">100%</option><option value="0.8">80%</option>
    <option value="0.6">60%</option><option value="0.4">40%</option><option value="0.25">25%</option>
  </select>
  <div class="sep"></div>
  <div class="lbl">Ligand</div>
  <select id="lig_style" class="ctl">
    <option value="stick">Sticks</option><option value="ball_stick">Ball+Stick</option>
    <option value="sphere">Spheres</option><option value="line">Lines</option>
  </select>
  <select id="lig_carbon" class="ctl">
    <option value="green">Green C</option><option value="cyan">Cyan C</option>
    <option value="magenta">Magenta C</option><option value="orange">Orange C</option>
    <option value="yellow">Yellow C</option><option value="purple">Purple C</option>
    <option value="white">White C</option>
  </select>
</div>

<div class="row">
  __CONTACT_CONTROLS__
  <label class="chk"><input type="checkbox" id="pocket_surf" class="ctl">Pocket surface</label>
  <label class="chk"><input type="checkbox" id="outline" class="ctl">Outline</label>
  <label class="chk"><input type="checkbox" id="ortho" class="ctl">Orthographic</label>
  <div class="lbl">Background</div>
  <select id="viewer_bg" class="ctl">
    <option value="#ffffff">White</option><option value="#f2f2f2">Light grey</option>
    <option value="#1a1f2e">Dark</option><option value="#000000">Black</option>
  </select>
  <div class="sep"></div>
  <button onclick="viewer.zoomTo({model:M.lig}); viewer.zoom(0.9); viewer.render();">Reset view</button>
  <button id="spin_btn" onclick="toggleSpin()">Spin</button>
  <div class="sep"></div>
  <div class="lbl">Export</div>
  <select id="exp_scale">
    <option value="1">Screen (1x)</option>
    <option value="3" selected>~300 dpi (3x)</option>
    <option value="6">~600 dpi (6x)</option>
    <option value="9">~900 dpi (9x)</option>
  </select>
  <label class="chk"><input type="checkbox" id="exp_transp">Transparent bg</label>
  <button class="primary" onclick="exportPNG()">Export PNG</button>
  <span class="badge">AutoDock Vina &nbsp;&middot;&nbsp; __AFF__</span>
  __NPOSES_BADGE__
</div>

<div id="info">
  <b>Protein:</b> __PROT__ &nbsp;&middot;&nbsp; <b>Ligand:</b> __LIGNAME__
  &nbsp;&middot;&nbsp; <b>Best affinity:</b> __AFF__
  &nbsp;&middot;&nbsp; <span style="color:#999;font-size:10px;">Drag to rotate &middot; Scroll to zoom &middot; Right-drag to translate</span>
  __LEGEND__
</div>

<script>
var REC = __REC__;
var LIG = __LIG__;
var LIGFMT = __LIGFMT__;
var EXTRA = __EXTRA__;
var HAS_CONTACTS = __HASCONTACTS__;
var CONTACT_PDB = __CONTACT_PDB__;
var CONTACTS = __CONTACT_JSON__;
var CCOL = __COLORS__;
var FILE_STEM = __FILESTEM__;

var LIG_CARBON = {green:'greenCarbon', cyan:'cyanCarbon', magenta:'magentaCarbon',
                  orange:'orangeCarbon', yellow:'yellowCarbon', purple:'purpleCarbon', white:'whiteCarbon'};
var REC_COLORS = {pale:'#c5d0de', white:'#ffffff', grey:'#b8b8b8'};

var PRESETS = {
  publication: {rec_style:'cartoon', rec_color:'pale', cart_op:'0.6', lig_style:'stick', lig_carbon:'green',
                viewer_bg:'#ffffff', res_color:'grey', show_contacts:true, show_dist:true,
                pocket_surf:false, outline:false, ortho:false},
  interactive: {rec_style:'cartoon', rec_color:'spectrum', cart_op:'1', lig_style:'stick', lig_carbon:'green',
                viewer_bg:'#1a1f2e', res_color:'type', show_contacts:true, show_dist:false,
                pocket_surf:false, outline:false, ortho:false}
};

function el(id) { return document.getElementById(id); }
function chk(id) { var e = el(id); return e ? e.checked : false; }
function val(id) { var e = el(id); return e ? e.value : null; }

var viewer = $3Dmol.createViewer("viewer", {backgroundColor: "#ffffff", antialias: true});
var spinning = false;

// Loads every model in a fixed order, so model indices are identical in
// the on-screen viewer and in the off-screen export viewer.
function populate(v) {
  v.addModel(REC, 'pdb');
  v.addModel(LIG, LIGFMT);
  var idx = [1];
  EXTRA.forEach(function(b) { v.addModel(b, LIGFMT); idx.push(v.getModelList().length - 1); });
  var cidx = -1;
  if (HAS_CONTACTS) { v.addModel(CONTACT_PDB, 'pdb'); cidx = v.getModelList().length - 1; }
  return {lig: idx, contact: cidx};
}
var M = populate(viewer);

function readOpts() {
  return {
    recStyle: val('rec_style'), recColor: val('rec_color'), cartOp: parseFloat(val('cart_op')),
    ligStyle: val('lig_style'), ligCarbon: val('lig_carbon'),
    showContacts: HAS_CONTACTS ? chk('show_contacts') : false,
    showDist: HAS_CONTACTS ? chk('show_dist') : false,
    resColor: HAS_CONTACTS ? val('res_color') : 'grey',
    pocketSurf: chk('pocket_surf'), outline: chk('outline'), ortho: chk('ortho'),
    bg: val('viewer_bg')
  };
}

function merge(a, b) { var r = {}, k; for (k in a) r[k] = a[k]; for (k in b) r[k] = b[k]; return r; }

function recBase(o) {
  if (o.recColor === 'spectrum') return {color: 'spectrum'};
  if (o.recColor === 'chain')    return {colorscheme: 'chain'};
  if (o.recColor === 'ss')       return {colorscheme: 'ssPyMol'};
  return {color: REC_COLORS[o.recColor] || '#ffffff'};
}

function ligStyleSpec(ls, scheme, opacity) {
  if (ls === 'stick')      return {stick: {colorscheme: scheme, opacity: opacity, radius: 0.2}};
  if (ls === 'sphere')     return {sphere: {colorscheme: scheme, opacity: opacity}};
  if (ls === 'ball_stick') return {stick: {colorscheme: scheme, opacity: opacity, radius: 0.12},
                                   sphere: {colorscheme: scheme, scale: 0.25, opacity: opacity}};
  if (ls === 'line')       return {line: {colorscheme: scheme, opacity: opacity}};
  return {};
}

function titleCase(s) { return s.charAt(0) + s.slice(1).toLowerCase(); }

// fs = label scale factor (1 on screen; >1 only in the export fallback path)
function styleScene(v, M, o, fs) {
  v.removeAllSurfaces(); v.removeAllLabels(); v.removeAllShapes();
  v.setBackgroundColor(o.bg);
  v.setStyle({model: 0}, {});
  M.lig.forEach(function(i) { v.setStyle({model: i}, {}); });
  if (M.contact >= 0) v.setStyle({model: M.contact}, {});

  // --- receptor ---
  var rb = recBase(o), rs = o.recStyle;
  if (rs === 'cartoon')      v.setStyle({model: 0}, {cartoon: merge(rb, {opacity: o.cartOp, arrows: true})});
  else if (rs === 'surface') {
    v.setStyle({model: 0}, {cartoon: merge(rb, {opacity: 0.3})});
    v.addSurface($3Dmol.SurfaceType.VDW, {opacity: 0.6, color: '#dde3ea'}, {model: 0});
  }
  else if (rs === 'line')    v.setStyle({model: 0}, {line: rb});
  else if (rs === 'stick')   v.setStyle({model: 0}, {stick: merge(rb, {radius: 0.1})});
  else if (rs === 'sphere')  v.setStyle({model: 0}, {sphere: merge(rb, {scale: 0.4})});

  if (o.pocketSurf) {
    v.addSurface($3Dmol.SurfaceType.VDW, {opacity: 0.35, color: '#9db4cc'},
                 {model: 0, within: {distance: 7, sel: {model: M.lig[0]}}}, {model: 0});
  }

  // --- ligand: best pose opaque, extra poses muted ---
  var carbon = LIG_CARBON[o.ligCarbon] || 'greenCarbon';
  M.lig.forEach(function(i, k) {
    v.setStyle({model: i}, k === 0 ? ligStyleSpec(o.ligStyle, carbon, 1.0)
                                   : ligStyleSpec(o.ligStyle, 'grayCarbon', 0.45));
  });

  // --- binding-site residues, labels, interaction dashes ---
  if (HAS_CONTACTS && o.showContacts) {
    var chains = {};
    CONTACTS.forEach(function(c) { chains[c.chain] = 1; });
    var multiChain = Object.keys(chains).length > 1;
    CONTACTS.forEach(function(c) {
      var col = CCOL[c.interaction] || CCOL['contact'];
      var spec = (o.resColor === 'type') ? {stick: {color: col, radius: 0.11}}
                                         : {stick: {colorscheme: 'grayCarbon', radius: 0.11}};
      v.setStyle({model: M.contact, chain: c.chain, resi: c.resnum}, spec);
      v.addLabel(titleCase(c.resname) + c.resnum + (multiChain ? ' (' + c.chain + ')' : ''), {
        position: {x: c.centroid[0], y: c.centroid[1], z: c.centroid[2]},
        backgroundColor: '#ffffff', backgroundOpacity: 0.72,
        fontColor: '#111111', fontSize: 11 * fs, bold: true,
        borderThickness: 0, inFront: true
      });
      if (c.hbond_pair) {
        var a = c.hbond_pair.res, b = c.hbond_pair.lig;
        v.addCylinder({start: {x: a[0], y: a[1], z: a[2]}, end: {x: b[0], y: b[1], z: b[2]},
                       radius: 0.05, color: col, dashed: true, dashLength: 0.2, gapLength: 0.12,
                       fromCap: 1, toCap: 1});
        if (o.showDist) {
          var d = Math.sqrt(Math.pow(a[0]-b[0],2) + Math.pow(a[1]-b[1],2) + Math.pow(a[2]-b[2],2));
          v.addLabel(d.toFixed(2) + ' \u00c5', {
            position: {x: (a[0]+b[0])/2, y: (a[1]+b[1])/2, z: (a[2]+b[2])/2},
            backgroundColor: '#ffffff', backgroundOpacity: 0.8,
            fontColor: col, fontSize: 10 * fs, bold: true, borderThickness: 0, inFront: true
          });
        }
      }
    });
  }

  try { v.setViewStyle(o.outline ? {style: 'outline', color: 'black', width: 0.05} : {style: 'none'}); } catch (e) {}
  try { v.setProjection(o.ortho ? 'orthographic' : 'perspective'); } catch (e) {}
  v.render();
}

function refresh() { styleScene(viewer, M, readOpts(), 1); }

function applyPreset(name) {
  var p = PRESETS[name]; if (!p) return;
  Object.keys(p).forEach(function(k) {
    var e = el(k); if (!e) return;
    if (e.type === 'checkbox') e.checked = !!p[k]; else e.value = p[k];
  });
  refresh();
}

function toggleSpin() {
  spinning = !spinning; viewer.spin(spinning);
  el('spin_btn').textContent = spinning ? 'Stop' : 'Spin';
}

// ---------------- high-resolution PNG export ----------------
// Re-creates the scene in a hidden, larger viewer so the export is not
// limited to the on-screen canvas size. Attempt 1 raises devicePixelRatio
// (canvas pixels = CSS size x scale). If the library ignores that, attempt 2
// enlarges the canvas itself and scales label fonts to match.
function renderOffscreen(scale, transparent) {
  var W = el('viewer').clientWidth, H = el('viewer').clientHeight;
  var host = document.createElement('div');
  host.style.cssText = 'position:fixed;left:-99999px;top:0;width:' + W + 'px;height:' + H + 'px;';
  document.body.appendChild(host);
  var oldDPR = window.devicePixelRatio, o = readOpts(), v2 = null;
  function setDPR(x) { try { Object.defineProperty(window, 'devicePixelRatio', {value: x, configurable: true}); } catch (e) {} }
  function attempt(cssScale, dpr) {
    if (v2) { try { v2.clear(); } catch (e) {} }
    host.innerHTML = '';
    host.style.width = (W * cssScale) + 'px'; host.style.height = (H * cssScale) + 'px';
    setDPR(dpr);
    v2 = $3Dmol.createViewer(host, {backgroundColor: o.bg, antialias: true});
    var M2 = populate(v2);
    styleScene(v2, M2, o, cssScale);
    v2.setView(viewer.getView());
    if (transparent) v2.setBackgroundColor(o.bg, 0);
    v2.render();
    return v2.getCanvas().width;
  }
  try {
    var w = attempt(1, scale);
    if (w < W * scale * 0.9) w = attempt(scale, 1);
    return {uri: v2.pngURI(), width: w};
  } finally {
    setDPR(oldDPR);
    try { v2.clear(); } catch (e) {}
    document.body.removeChild(host);
  }
}

function exportPNG() {
  var scale = parseInt(val('exp_scale'), 10) || 1, transparent = chk('exp_transp');
  try {
    var out;
    if (scale === 1 && !transparent) { viewer.render(); out = {uri: viewer.pngURI()}; }
    else out = renderOffscreen(scale, transparent);
    var a = document.createElement('a');
    if (out.width && scale > 1 && out.width < el('viewer').clientWidth * scale * 0.9)
      alert('Your browser limited the canvas to ' + out.width + ' px wide. Try a lower setting.');
    a.href = out.uri; a.download = FILE_STEM + '_' + scale + 'x.png';
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
  } catch (e) { alert('PNG export failed: ' + e); }
}

// ---------------- wire up ----------------
var ctls = document.querySelectorAll('.ctl');
for (var i = 0; i < ctls.length; i++) ctls[i].onchange = refresh;
el('preset').onchange = function() { applyPreset(this.value); };
applyPreset('__DEFAULT_PRESET__');
el('preset').value = '__DEFAULT_PRESET__';
viewer.zoomTo({model: M.lig});
viewer.zoom(0.9);
viewer.render();
</script>
</body></html>"""


def build_viewer_html(receptor_pdb: str, ligand_pdb: str,
                      protein_name: str, ligand_name: str,
                      affinity: float | None,
                      lig_format: str = "pdb",
                      contacts: list | None = None,
                      contact_pdb: str = "",
                      extra_lig_poses: list | None = None,
                      default_preset: str = "publication") -> str:
    """Build a self-contained 3Dmol.js viewer page.

    lig_format should be 'sdf' when the ligand string was converted via Open
    Babel (preserves bond orders). Falls back to 'pdb' otherwise.

    contacts / contact_pdb (optional): output of compute_ligand_contacts() /
    filter_pdb_to_residues(). Adds a binding-site layer: residue sticks,
    residue labels, and dashed cylinders with distance labels for H-bond /
    salt-bridge pairs. Always computed against ``ligand_pdb`` (the primary
    pose) even when extra_lig_poses are rendered.

    extra_lig_poses (optional): additional single-pose text blocks (same
    lig_format as ligand_pdb), each loaded as its own model because 3Dmol's
    addModel only shows the first frame of a multi-pose string.

    default_preset: "publication" (white background, pale translucent
    cartoon, grey pocket residues, distance labels) or "interactive" (the
    original dark look). The in-viewer Preset menu switches between them.
    """
    def _js(s: str) -> str:
        # json.dumps gives a valid JS string literal; also neutralise "</"
        # so a stray "</script>" in input can never end the script block.
        return json.dumps(s).replace("</", "<\\/")

    aff_str = f"{affinity:.2f} kcal/mol" if affinity is not None else "N/A"
    extra = list(extra_lig_poses or [])
    n_poses_total = 1 + len(extra)
    has_contacts = bool(contacts) and bool(contact_pdb.strip())

    contact_json = json.dumps([
        {k: c[k] for k in ("chain", "resnum", "resname", "residue",
                            "min_dist", "interaction", "detail",
                            "centroid", "hbond_pair")}
        for c in (contacts or [])
    ])

    contact_controls = ""
    legend = ""
    if has_contacts:
        contact_controls = (
            '<label class="chk"><input type="checkbox" id="show_contacts" class="ctl" checked>'
            'Binding-site residues</label>'
            '<label class="chk"><input type="checkbox" id="show_dist" class="ctl" checked>'
            'Distance labels</label>'
            '<div class="lbl">Residue colour</div>'
            '<select id="res_color" class="ctl">'
            '<option value="grey">Neutral (grey C)</option>'
            '<option value="type">By interaction type</option></select>'
        )
        legend = (
            '&nbsp;&middot;&nbsp;'
            '<span style="color:#e63946;">&#9632;</span> H-bond '
            '<span style="color:#2a9d8f;">&#9632;</span> Salt bridge '
            '<span style="color:#f4a300;">&#9632;</span> Hydrophobic '
            '<span style="color:#8338ec;">&#9632;</span> &pi;-stacking '
            '<span style="color:#adb5bd;">&#9632;</span> Contact'
        )

    stem = _re.sub(r"[^A-Za-z0-9_.-]", "_", f"IBDock_Provenire_{protein_name}_{ligand_name}_pose")
    preset = default_preset if default_preset in ("publication", "interactive") else "publication"

    repl = {
        "__CONTACT_CONTROLS__": contact_controls,
        "__NPOSES_BADGE__": (f'<span class="badge">{n_poses_total} poses shown</span>'
                             if n_poses_total > 1 else ""),
        "__LEGEND__": legend,
        "__AFF__": _html.escape(aff_str),
        "__PROT__": _html.escape(str(protein_name)),
        "__LIGNAME__": _html.escape(str(ligand_name)),
        "__REC__": _js(receptor_pdb),
        "__LIG__": _js(ligand_pdb),
        "__LIGFMT__": _js(lig_format),
        "__EXTRA__": json.dumps(extra).replace("</", "<\\/"),
        "__HASCONTACTS__": "true" if has_contacts else "false",
        "__CONTACT_PDB__": _js(contact_pdb if has_contacts else ""),
        "__CONTACT_JSON__": contact_json,
        "__COLORS__": json.dumps(_CONTACT_COLORS),
        "__FILESTEM__": _js(stem),
        "__DEFAULT_PRESET__": preset,
    }
    out = _VIEWER_TEMPLATE
    for token, value in repl.items():
        out = out.replace(token, value)
    return out


# ──────────────────────────────────────────────────────────────────────────────
# PUBLICATION FIGURES: 2D interaction diagram
# ──────────────────────────────────────────────────────────────────────────────

_PUB_RES_CLASS = {
    "ALA": "hydrophobic", "VAL": "hydrophobic", "LEU": "hydrophobic", "ILE": "hydrophobic",
    "MET": "hydrophobic", "PHE": "hydrophobic", "TRP": "hydrophobic", "PRO": "hydrophobic",
    "SER": "polar", "THR": "polar", "ASN": "polar", "GLN": "polar",
    "TYR": "polar", "CYS": "polar", "HIS": "polar",
    "LYS": "positive", "ARG": "positive",
    "ASP": "negative", "GLU": "negative",
    "GLY": "glycine",
}
_PUB_RES_COLORS = {
    "hydrophobic": "#9bd49b", "polar": "#8fd3e8", "positive": "#b7a4e3",
    "negative": "#f0a3a3", "glycine": "#e3e3e3", "other": "#f4f4f4",
}
_PUB_RES_LABELS = {
    "hydrophobic": "Hydrophobic", "polar": "Polar", "positive": "Positively charged",
    "negative": "Negatively charged", "glycine": "Glycine", "other": "Other",
}
_PUB_ELEM_COLORS = {"N": "#2540c8", "O": "#d62828", "S": "#b38600",
                    "F": "#2e8b57", "Cl": "#2e8b57", "Br": "#8b2e2e", "I": "#6a2e8b", "P": "#c66a00"}
_PUB_INTERACTION_RANK = {"salt-bridge": 0, "H-bond": 1, "pi-stacking": 2, "hydrophobic": 3, "contact": 4}
_PUB_INTERACTION_NAMES = {
    "H-bond": "H-bond", "salt-bridge": "Salt bridge", "pi-stacking": "\u03c0-stacking (centroid)",
    "hydrophobic": "Hydrophobic contact", "contact": "Other contact",
}

def _first_sdf_block(text: str) -> str:
    """First molecule of an SDF string. Only trailing whitespace is trimmed:
    the first line of a mol block is the (possibly empty) title and must stay."""
    if not text.strip():
        return ""
    return text.split("$$$$")[0].rstrip() + "\n"


_BS_TAG_CLASS = {"H-bond": "info", "salt-bridge": "warn", "pi-stacking": "pi",
                 "hydrophobic": "ok", "contact": "mute"}
_BS_LABEL = {"H-bond": "H-bond", "salt-bridge": "Salt bridge", "pi-stacking": "Pi-stacking",
             "hydrophobic": "Hydrophobic", "contact": "Contact"}
_BS_KEY_TYPES = ("H-bond", "salt-bridge", "pi-stacking")


def render_binding_site_table_html(contacts: list) -> str:
    """Binding-site residue summary + table as app-styled HTML.

    Single-line HTML (Markdown-safe). Residue dots reuse the residue-class
    colours of the 2D interaction diagram; rows with a specific interaction
    (H-bond, salt bridge, pi-stacking) carry a navy accent edge.
    """
    import html as _html

    counts = {}
    for c in contacts:
        counts[c["interaction"]] = counts.get(c["interaction"], 0) + 1
    chains = sorted({c["chain"] for c in contacts if c["chain"]})
    summary = (
        f'<div class="bs-summary"><b>{len(contacts)} residue{"" if len(contacts) == 1 else "s"}</b>'
        f' within 4.5 &Aring;'
        + (f' &middot; chain{"s" if len(chains) > 1 else ""} {_html.escape(", ".join(chains))}' if chains else "")
        + '<span class="bs-sep"></span>'
        + "".join(_lig_tag(f"{_BS_LABEL.get(k, k)} {counts[k]}", _BS_TAG_CLASS.get(k, "mute"))
                  for k in _BS_LABEL if counts.get(k))
        + "</div>"
    )

    rows = []
    for c in contacts:
        ixn  = c["interaction"]
        rcls = _PUB_RES_CLASS.get(c["resname"], "other")
        dot  = (f'<span class="rdot" title="{_html.escape(_PUB_RES_LABELS[rcls], quote=True)}" '
                f'style="background:{_PUB_RES_COLORS[rcls]}; border-color:{_PUB_RES_EDGE[rcls]};"></span>')
        rows.append(
            f'<tr class="{"key" if ixn in _BS_KEY_TYPES else ""}">'
            f'<td><span class="res">{dot}{_html.escape(str(c["resname"]))} {_html.escape(str(c["resnum"]))}</span></td>'
            f'<td class="mono">{_html.escape(str(c["chain"]) or "-")}</td>'
            f'<td>{_lig_tag(_BS_LABEL.get(ixn, ixn), _BS_TAG_CLASS.get(ixn, "mute"))}</td>'
            f'<td class="num mono">{float(c["min_dist"]):.2f}</td>'
            f'<td class="det">{_html.escape(str(c["detail"]))}</td></tr>'
        )
    table = (
        '<div class="bs-wrap"><table class="bs-table"><thead><tr>'
        '<th>Residue</th><th>Chain</th><th>Interaction</th>'
        '<th class="num">Min. distance (&Aring;)</th><th>Key atom pair</th>'
        '</tr></thead><tbody>' + "".join(rows) + '</tbody></table></div>'
    )
    legend = (
        '<div class="bs-legend">Residue colour: '
        + "".join(
            f'<span class="rdot" style="background:{_PUB_RES_COLORS[k]}; border-color:{_PUB_RES_EDGE[k]};"></span>'
            f'{_html.escape(_PUB_RES_LABELS[k])}'
            for k in ("hydrophobic", "polar", "positive", "negative", "glycine"))
        + "</div>"
    )
    return summary + table + legend


_PUB_RES_COLORS = {
    "hydrophobic": "#8fd18f", "polar": "#7fd0ea", "positive": "#b9a3e6",
    "negative": "#f29a9a", "glycine": "#e6e6e6", "other": "#f5f5f5",
}
_PUB_RES_EDGE = {
    "hydrophobic": "#4f9a4f", "polar": "#3a9bbd", "positive": "#7b61c4",
    "negative": "#d05a5a", "glycine": "#9a9a9a", "other": "#aaaaaa",
}
_PUB_IXN = {
    "hbond": "#e0457b", "salt_pos": "#1f4fd8", "salt_neg": "#d62728",
    "pi": "#2e9e44", "weak": "#b0b0b0", "halo": "#a9d3f5",
}
_PUB_VDW = {"C": 1.70, "N": 1.55, "O": 1.52, "S": 1.80, "P": 1.80, "F": 1.47,
            "Cl": 1.75, "Br": 1.85, "I": 1.98}


def _pt_seg_dist(P, A, B):
    """Distances from points P (m,2) to segments A-B (k,2) -> (m,k)."""
    P = np.asarray(P, float)[:, None, :]
    A = np.asarray(A, float)[None, :, :]
    B = np.asarray(B, float)[None, :, :]
    AB = B - A
    L2 = np.maximum((AB ** 2).sum(-1), 1e-9)
    t = np.clip(((P - A) * AB).sum(-1) / L2, 0.0, 1.0)
    return np.linalg.norm(P - (A + t[..., None] * AB), axis=-1)


def _segs_cross(P1, P2, Q1, Q2):
    """True where segment P1-P2 properly crosses Q1-Q2 (P1 is (m,2))."""
    def orient(a, b, c):
        return (b[..., 0] - a[..., 0]) * (c[..., 1] - a[..., 1]) - (b[..., 1] - a[..., 1]) * (c[..., 0] - a[..., 0])
    return (orient(Q1, Q2, P1) * orient(Q1, Q2, P2) < 0) & (orient(P1, P2, Q1) * orient(P1, P2, Q2) < 0)


def _ligand_exposure_fractions(lig_xyz, lig_elems, rec_xyz, rec_elems, n_pts=96, probe=1.4):
    """Shrake-Rupley-style fraction of each ligand atom's surface still
    reachable by a water probe in the complex (0 = buried, 1 = exposed)."""
    k = np.arange(n_pts) + 0.5
    phi = np.arccos(1 - 2 * k / n_pts)
    theta = np.pi * (1 + 5 ** 0.5) * k
    sph = np.stack([np.cos(theta) * np.sin(phi), np.sin(theta) * np.sin(phi), np.cos(phi)], axis=1)

    def rad(e):
        return _PUB_VDW.get(e, _PUB_VDW.get(str(e)[:1].upper(), 1.8))

    all_xyz = np.vstack([lig_xyz, rec_xyz]) if len(rec_xyz) else lig_xyz
    all_rad = np.array([rad(e) for e in list(lig_elems) + list(rec_elems)]) + probe
    n_lig = len(lig_xyz)
    fracs = np.zeros(n_lig)
    for i in range(n_lig):
        ri = all_rad[i]
        pts = lig_xyz[i] + sph * ri
        near = np.where(np.linalg.norm(all_xyz - lig_xyz[i], axis=1) < ri + all_rad.max())[0]
        near = near[near != i]
        if len(near) == 0:
            fracs[i] = 1.0
            continue
        d = np.linalg.norm(pts[:, None, :] - all_xyz[near][None, :, :], axis=-1)
        blocked = (d < all_rad[near][None, :]).any(axis=1)
        fracs[i] = 1.0 - blocked.mean()
    return fracs


def render_interaction_diagram_2d(receptor_pdb: str, ligand_text: str, lig_format: str,
                                  contacts: list, title: str = "", subtitle: str = "",
                                  dpi: int = 300, max_residues: int = 40,
                                  weak_lines: bool = False, show_halo: bool = True,
                                  auto_orient: bool = True) -> dict:
    """Publication-style 2D ligand-interaction diagram.

    Layout: every residue bubble is placed next to the ligand atom it
    actually touches (greedy search over angle/radius candidates with hard
    constraints: no overlap with ligand bonds or other bubbles, no connector
    line through the ligand). Only specific interactions get connector lines
    (H-bond arrows pointing at the acceptor, two-tone salt-bridge lines,
    pi-stacking lines to the ring centre); hydrophobic/other contacts are
    shown as coloured bubbles with no line unless ``weak_lines`` is True.
    Light-blue halos mark solvent-exposed ligand atoms (Shrake-Rupley, computed
    from the full receptor). The canvas is sized to the drawing, so there is
    no dead space.

    Returns {"png","preview","svg","pdf","n_shown","n_omitted","px"}.
    ``png`` is rendered at ``dpi``; ``preview`` is a light 110-dpi copy for
    on-screen display; svg/pdf are vector with editable text.
    """
    if not _RMSD_DEPS_OK:
        raise RuntimeError(f"RDKit is required for the 2D diagram ({_RMSD_DEPS_ERROR}).")
    if lig_format != "sdf":
        raise ValueError("The 2D diagram needs bond orders, so the ligand must load as SDF "
                         "(set a valid Open Babel path in the sidebar).")
    if not contacts:
        raise ValueError("No binding-site residues to draw.")

    import math
    import matplotlib
    from matplotlib.figure import Figure
    from matplotlib.patches import Circle, FancyArrowPatch, Patch
    from matplotlib.lines import Line2D
    from rdkit.Chem import rdDepictor

    block = _first_sdf_block(ligand_text)
    mol = _Chem.MolFromMolBlock(block, sanitize=True, removeHs=False) \
        or _Chem.MolFromMolBlock(block, sanitize=False, removeHs=False)
    if mol is None:
        raise ValueError("Could not parse the ligand pose.")
    parsed = _ligand_atoms_from_sdf(block)
    try:
        heavy = _Chem.RemoveHs(mol)
    except Exception:
        heavy = _Chem.RemoveHs(mol, sanitize=False)
    heavy.UpdatePropertyCache(strict=False)
    n_at = heavy.GetNumAtoms()
    xyz3 = np.array(heavy.GetConformer().GetPositions())
    lig_sym = [a.GetSymbol() for a in heavy.GetAtoms()]

    # ---- 2D depiction (CoordGen if available), principal axis horizontal ----
    m2 = _Chem.Mol(heavy)
    try:
        rdDepictor.SetPreferCoordGen(True)
    except Exception:
        pass
    rdDepictor.Compute2DCoords(m2)
    xy = np.array(m2.GetConformer().GetPositions())[:, :2]
    if auto_orient and n_at > 3:
        cc = xy - xy.mean(axis=0)
        _u, sv, vt = np.linalg.svd(cc, full_matrices=False)
        if sv[0] / max(sv[1], 1e-6) > 1.25:
            ang0 = -math.atan2(vt[0][1], vt[0][0])
            R = np.array([[math.cos(ang0), -math.sin(ang0)], [math.sin(ang0), math.cos(ang0)]])
            xy = cc @ R.T + xy.mean(axis=0)
    kek = _Chem.Mol(m2)
    try:
        _Chem.Kekulize(kek, clearAromaticFlags=False)
    except Exception:
        pass
    bonds = [(b.GetBeginAtomIdx(), b.GetEndAtomIdx()) for b in kek.GetBonds()]
    bondA = np.array([xy[i] for i, j in bonds])
    bondB = np.array([xy[j] for i, j in bonds])
    ring_info = m2.GetRingInfo().AtomRings()
    arom_rings = [list(r) for r in ring_info if all(heavy.GetAtomWithIdx(a).GetIsAromatic() for a in r)] \
        or [list(r) for r in ring_info if len(r) >= 5]

    # ---- donor / acceptor flags per ligand heavy atom ----
    lig_flags = {}
    for j in range(n_at):
        at = heavy.GetAtomWithIdx(j)
        sym, nh = at.GetSymbol(), at.GetTotalNumHs()
        lig_flags[j] = (sym in ("N", "O") and nh > 0, sym == "O" or (sym == "N" and nh == 0))
    if parsed is not None and parsed[0]:
        pa = parsed[0]
        PP = np.array([[a["x"], a["y"], a["z"]] for a in pa])
        for j in range(n_at):
            k = int(np.argmin(np.linalg.norm(PP - xyz3[j], axis=1)))
            if np.linalg.norm(PP[k] - xyz3[j]) < 0.05:
                lig_flags[j] = (bool(pa[k].get("is_donor")), bool(pa[k].get("is_acceptor")))

    residues = _parse_receptor_pdb_residues(receptor_pdb)

    # ---- solvent exposure of ligand atoms ----
    fracs = np.zeros(n_at)
    if show_halo:
        try:
            rxyz, relem = [], []
            for atoms in residues.values():
                for a in atoms:
                    rxyz.append([a["x"], a["y"], a["z"]])
                    relem.append(a["element"])
            rxyz = np.array(rxyz)
            keep = np.where(((rxyz[:, None, :] - xyz3[None, :, :]) ** 2).sum(-1).min(axis=1) < 18.0 ** 2)[0]
            fracs = _ligand_exposure_fractions(xyz3, lig_sym, rxyz[keep], [relem[i] for i in keep])
        except Exception:
            fracs = np.zeros(n_at)

    # ---- residue selection and anchors ----
    _rank = {"salt-bridge": 0, "H-bond": 1, "pi-stacking": 2, "hydrophobic": 3, "contact": 4}
    ranked = sorted(contacts, key=lambda c: (_rank.get(c["interaction"], 9), c["min_dist"]))
    shown, omitted = ranked[:max_residues], max(0, len(ranked) - max_residues)
    gcen = xy.mean(axis=0)

    def outward_angle(pt, exclude=()):
        d = np.linalg.norm(xy - pt, axis=1)
        sel = [k for k in range(n_at) if d[k] < 4.0 and d[k] > 1e-6 and k not in exclude]
        v = pt - (xy[sel].mean(axis=0) if sel else gcen)
        if np.linalg.norm(v) < 0.3:
            v = pt - gcen
        return math.atan2(v[1], v[0]) if np.linalg.norm(v) > 1e-6 else 0.0

    items = []
    for c in shown:
        atoms = residues.get((c["chain"], c["resnum"], c["resname"]))
        if not atoms:
            continue
        rxyz_c = np.array([[a["x"], a["y"], a["z"]] for a in atoms])
        itype, it = c["interaction"], {"c": c, "kind": "weak", "excl": set()}
        if itype in ("H-bond", "salt-bridge") and c.get("hbond_pair"):
            j = int(np.argmin(np.linalg.norm(xyz3 - np.array(c["hbond_pair"]["lig"]), axis=1)))
            it.update(kind=itype, atom=j, pt=xy[j].copy(), excl={j})
            an = c["detail"].split(" ")[0]
            it["res_atom"] = an
            it["res_xyz"] = np.array(c["hbond_pair"]["res"])
        elif itype == "pi-stacking" and arom_rings and _AROMATIC_RING_ATOMS.get(c["resname"]):
            rp = np.array([[a["x"], a["y"], a["z"]] for a in atoms if a["name"] in _AROMATIC_RING_ATOMS[c["resname"]]])
            if len(rp) >= 3:
                rc = rp.mean(axis=0)
                ring = min(arom_rings, key=lambda r: np.linalg.norm(xyz3[r].mean(axis=0) - rc))
                it.update(kind="pi-stacking", atom=ring[0], pt=xy[ring].mean(axis=0), excl=set(ring),
                          dist=float(np.linalg.norm(xyz3[ring].mean(axis=0) - rc)))
        if it["kind"] == "weak":
            dm = np.linalg.norm(rxyz_c[:, None, :] - xyz3[None, :, :], axis=-1)
            j = int(np.unravel_index(np.argmin(dm), dm.shape)[1])
            it.update(atom=j, pt=xy[j].copy(), excl={j})
        it["specific"] = it["kind"] != "weak"
        it["line"] = it["specific"] or weak_lines
        it["out"] = outward_angle(it["pt"], it["excl"])
        items.append(it)
    if not items:
        raise ValueError("Could not anchor any residue to the ligand.")

    # ---- greedy anchor-hugging placement ----
    rb = 0.72
    items.sort(key=lambda d: (0 if d["specific"] else 1, d["c"]["min_dist"]))
    angles = np.linspace(0, 2 * math.pi, 96, endpoint=False)
    radii = [rb + 1.05, rb + 1.6, rb + 2.3, rb + 3.1, rb + 4.1, rb + 5.3, rb + 6.8, rb + 8.5]
    placed, drawn = [], []
    for it in items:
        anchor = it["pt"]
        rlist = radii[1:] if it["specific"] else radii     # readable arrows/lines
        if it["kind"] == "salt-bridge":
            rlist = [r for r in radii if r >= rb + 2.3]
        if it["kind"] == "pi-stacking":                    # connector must clear the ring itself
            rlist = [r for r in radii if r >= rb + 2.5]
        cand = np.array([[anchor[0] + r * math.cos(a), anchor[1] + r * math.sin(a)]
                         for r in rlist for a in angles])
        cand_r = np.repeat(rlist, len(angles))
        cand_a = np.tile(angles, len(rlist))
        ok = (_pt_seg_dist(cand, bondA, bondB).min(axis=1) >= rb + 0.30)
        if placed:
            Q = np.array(placed)
            ok &= (np.linalg.norm(cand[:, None, :] - Q[None, :, :], axis=-1).min(axis=1) >= 2 * rb + 0.14)
        if it["line"]:
            keep_b = [k for k, (i, j) in enumerate(bonds) if i not in it["excl"] and j not in it["excl"]]
            if keep_b:
                ts = np.linspace(0.0, 1.0, 12)
                pts = cand[:, None, :] + (anchor - cand)[:, None, :] * ts[None, :, None]
                dpts = _pt_seg_dist(pts.reshape(-1, 2), bondA[keep_b], bondB[keep_b]).min(axis=1).reshape(len(cand), -1)
                near_anchor = np.linalg.norm(pts - anchor, axis=-1) < 0.6
                dpts = np.where(near_anchor, 9.0, dpts)
                ok &= (dpts.min(axis=1) >= 0.27)
            if placed:
                Q = np.array(placed)
                ok &= (_pt_seg_dist(Q, cand, np.tile(anchor, (len(cand), 1))).min(axis=0) >= rb + 0.10)
            for (s, e) in drawn:
                ok &= (_pt_seg_dist(cand, np.array([s]), np.array([e])).min(axis=1) >= rb + 0.10)
        cost = 1.7 * (((cand_a - it["out"] + math.pi) % (2 * math.pi) - math.pi) ** 2) \
            + 0.9 * (cand_r - radii[0])
        if it["line"]:
            for (s, e) in drawn:
                cost = cost + 4.0 * _segs_cross(cand, anchor, s, e)
        cost = np.where(ok, cost, np.inf)
        k = int(np.argmin(cost))
        if not np.isfinite(cost[k]):          # extremely crowded: take least-bad spot
            k = int(np.argmax(_pt_seg_dist(cand, bondA, bondB).min(axis=1)))
        it["pos"] = cand[k]
        placed.append(cand[k])
        if it["line"]:
            drawn.append((cand[k].copy(), anchor.copy()))

    # ---- canvas sized to the drawing ----
    allp = np.vstack([xy] + [np.array([d["pos"]]) for d in items])
    x0, x1 = allp[:, 0].min() - rb - 0.45, allp[:, 0].max() + rb + 0.45
    y0, y1 = allp[:, 1].min() - rb - 0.45, allp[:, 1].max() + rb + 0.45
    ext_x, ext_y = x1 - x0, y1 - y0
    scale = 0.40
    if ext_x * scale > 11.0:
        scale = 11.0 / ext_x
    Wd = max(7.4, ext_x * scale)
    Hax = ext_y * scale
    top = 0.62 if (title or subtitle) else 0.10
    bottom = 1.22
    Hd = Hax + top + bottom
    cxm, cym = (x0 + x1) / 2, (y0 + y1) / 2
    xs, ys = Wd / scale, Hax / scale

    rc = {"svg.fonttype": "none", "pdf.fonttype": 42, "font.family": "sans-serif",
          "font.sans-serif": ["Arial", "Helvetica", "DejaVu Sans"]}
    elem_col = {"N": "#2540c8", "O": "#d62828", "S": "#b38600", "F": "#2e8b57", "Cl": "#2e8b57",
                "Br": "#8b2e2e", "I": "#6a2e8b", "P": "#c66a00"}
    with matplotlib.rc_context(rc):
        fig = Figure(figsize=(Wd, Hd))
        ax = fig.add_axes([0, bottom / Hd, 1, Hax / Hd])
        ax.set_xlim(cxm - xs / 2, cxm + xs / 2)
        ax.set_ylim(cym - ys / 2, cym + ys / 2)
        ax.set_aspect("equal", adjustable="box")
        ax.axis("off")

        def hetero_label(a):
            sym = a.GetSymbol()
            if sym == "C":
                return None
            h = a.GetTotalNumHs()
            txt = sym + ("H" if h == 1 else (f"H$_{{{h}}}$" if h > 1 else ""))
            chg = a.GetFormalCharge()
            if chg:
                txt += "$^{+}$" if chg > 0 else "$^{-}$"
            return txt

        labels = {a.GetIdx(): hetero_label(a) for a in kek.GetAtoms()}
        shrink = 0.34

        # solvent-exposure halos
        if show_halo:
            for j in range(n_at):
                if fracs[j] > 0.08:
                    ax.add_patch(Circle(xy[j], 0.45 + 0.70 * fracs[j], fc=_PUB_IXN["halo"],
                                        ec="none", alpha=0.6, zorder=1))

        # ligand bonds
        def ring_centroid(i, j):
            best = None
            for r in ring_info:
                if i in r and j in r and (best is None or len(r) < len(best)):
                    best = r
            return xy[list(best)].mean(axis=0) if best else None

        for bnd in kek.GetBonds():
            i, j = bnd.GetBeginAtomIdx(), bnd.GetEndAtomIdx()
            p, q = xy[i].copy(), xy[j].copy()
            u = (q - p) / max(np.linalg.norm(q - p), 1e-6)
            if labels[i]:
                p = p + u * shrink
            if labels[j]:
                q = q - u * shrink
            order = bnd.GetBondTypeAsDouble()
            nrm = np.array([-u[1], u[0]])
            if order >= 2.9:
                segs = [(p + nrm * 0.14, q + nrm * 0.14), (p, q), (p - nrm * 0.14, q - nrm * 0.14)]
            elif 1.9 <= order < 2.9:
                rc_ = ring_centroid(i, j)
                if rc_ is not None:
                    side = 1 if np.dot(rc_ - (p + q) / 2, nrm) > 0 else -1
                    off = nrm * side * 0.2
                    segs = [(p, q), (p + off + u * 0.15, q + off - u * 0.15)]
                else:
                    segs = [(p + nrm * 0.1, q + nrm * 0.1), (p - nrm * 0.1, q - nrm * 0.1)]
            else:
                segs = [(p, q)]
            for s, e in segs:
                ax.plot([s[0], e[0]], [s[1], e[1]], color="#222222", lw=1.9, solid_capstyle="round", zorder=3)
        for a in kek.GetAtoms():
            lab = labels[a.GetIdx()]
            if lab:
                ax.text(xy[a.GetIdx(), 0], xy[a.GetIdx(), 1], lab, ha="center", va="center", fontsize=11,
                        fontweight="bold", color=elem_col.get(a.GetSymbol(), "#333333"), zorder=4,
                        bbox=dict(boxstyle="round,pad=0.10", fc="white", ec="none"))

        # connectors + bubbles
        multi_chain = len({d["c"]["chain"] for d in items}) > 1
        present_cls, present_ix = set(), set()
        pos_res, neg_res = {"LYS", "ARG", "HIS"}, {"ASP", "GLU"}

        def draw_line(a, b, col, ls="-", lw=1.7, arrow=False, label=None, lt=0.5, off=0.0):
            v = b - a
            L = max(np.linalg.norm(v), 1e-6)
            u = v / L
            if arrow:
                tail = b - u * 0.36
                ax.plot([a[0], tail[0]], [a[1], tail[1]], color=col, lw=lw, ls=ls, zorder=2.5,
                        dash_capstyle="butt", solid_capstyle="butt")
                ax.add_patch(FancyArrowPatch(tail, b, arrowstyle="-|>", mutation_scale=11, lw=lw,
                                             color=col, shrinkA=0, shrinkB=0, zorder=2.6))
            else:
                ax.plot([a[0], b[0]], [a[1], b[1]], color=col, lw=lw, ls=ls, zorder=2.5, solid_capstyle="butt")
            if label:
                m = a + (b - a) * lt + np.array([-u[1], u[0]]) * off
                ax.text(m[0], m[1], label, fontsize=7.5, color=col, ha="center", va="center", zorder=6,
                        fontweight="bold", bbox=dict(boxstyle="round,pad=0.10", fc="white", ec="none", alpha=0.92))

        for it in items:
            c, pos, anchor, kind = it["c"], it["pos"], it["pt"], it["kind"]
            cls = _PUB_RES_CLASS.get(c["resname"], "other")
            present_cls.add(cls)
            u = (anchor - pos) / max(np.linalg.norm(anchor - pos), 1e-6)
            start = pos + u * rb
            lig_end = anchor - u * (shrink if (labels.get(it["atom"]) and kind != "pi-stacking") else 0.04)
            ring_col, ring_lw = _PUB_RES_EDGE[cls], 1.0

            if kind == "H-bond":
                present_ix.add("hbond")
                ring_col, ring_lw = _PUB_IXN["hbond"], 2.3
                an = it.get("res_atom", "")
                res_don = an == "N" or an in _AA_DONOR_ATOMS.get(c["resname"], set())
                res_acc = an == "O" or an in _AA_ACCEPTOR_ATOMS.get(c["resname"], set())
                ldon, lacc = lig_flags.get(it["atom"], (False, False))
                if ldon and res_acc and not (lacc and res_don):
                    toward = "res"
                elif lacc and res_don and not (ldon and res_acc):
                    toward = "lig"
                else:
                    toward = "res" if ldon else "lig"
                side = an not in ("N", "O")
                lbl = f"{c['min_dist']:.1f}"
                if toward == "lig":
                    draw_line(start, lig_end, _PUB_IXN["hbond"], "--" if side else "-", arrow=True, label=lbl)
                else:
                    draw_line(lig_end, start, _PUB_IXN["hbond"], "--" if side else "-", arrow=True, label=lbl)
            elif kind == "salt-bridge":
                present_ix.add("salt")
                ring_col, ring_lw = _PUB_IXN["salt_pos"] if c["resname"] in pos_res else _PUB_IXN["salt_neg"], 2.3
                rcol = _PUB_IXN["salt_pos"] if c["resname"] in pos_res else _PUB_IXN["salt_neg"]
                lcol = _PUB_IXN["salt_neg"] if c["resname"] in pos_res else _PUB_IXN["salt_pos"]
                mid = (start + lig_end) / 2
                draw_line(start, mid, rcol, "-", lw=2.2)
                draw_line(mid, lig_end, lcol, "-", lw=2.2)
                ax.text(*mid, f"{c['min_dist']:.1f}", fontsize=7.5, color="#333333", ha="center",
                        va="center", zorder=6, fontweight="bold",
                        bbox=dict(boxstyle="round,pad=0.10", fc="white", ec="none", alpha=0.92))
            elif kind == "pi-stacking":
                present_ix.add("pi")
                ring_col, ring_lw = _PUB_IXN["pi"], 2.3
                draw_line(start, anchor, _PUB_IXN["pi"], "--", lw=1.8, label=f"{it.get('dist', c['min_dist']):.1f}", lt=0.28)
                ax.add_patch(Circle(anchor, 0.13, fc=_PUB_IXN["pi"], ec="white", lw=0.8, zorder=4.5))
            elif it["line"]:
                present_ix.add("weak")
                draw_line(start, lig_end, _PUB_IXN["weak"], ":", lw=1.0)

            ax.add_patch(Circle(pos, rb, fc=_PUB_RES_COLORS[cls], ec=ring_col, lw=ring_lw, zorder=5))
            txt = f"{c['resname'].capitalize()}\n{c['resnum']}" + (f"\n({c['chain']})" if multi_chain else "")
            ax.text(pos[0], pos[1], txt, ha="center", va="center", fontsize=7.6 if multi_chain else 8.4,
                    fontweight="bold", color="#111111", zorder=6, linespacing=0.95)

        if title:
            fig.text(0.5, 1 - 0.20 / Hd, title, ha="center", va="center", fontsize=13.5, fontweight="bold")
        if subtitle:
            fig.text(0.5, 1 - 0.46 / Hd, subtitle, ha="center", va="center", fontsize=9.5, color="#555555")

        # legends: residue classes (row 1), interactions (row 2), footnote
        cls_h = [Line2D([0], [0], marker="o", ls="none", markersize=10, mfc=_PUB_RES_COLORS[k],
                        mec=_PUB_RES_EDGE[k], label=_PUB_RES_LABELS[k])
                 for k in ("hydrophobic", "polar", "positive", "negative", "glycine", "other") if k in present_cls]
        ix_h = []
        if "hbond" in present_ix:
            ix_h += [Line2D([0], [0], color=_PUB_IXN["hbond"], lw=1.7, ls="-", marker=">", markersize=6,
                            markevery=[1], label="H-bond, backbone"),
                     Line2D([0], [0], color=_PUB_IXN["hbond"], lw=1.7, ls="--", marker=">", markersize=6,
                            markevery=[1], label="H-bond, side chain")]
        if "salt" in present_ix:
            ix_h.append((Line2D([0], [0], color=_PUB_IXN["salt_pos"], lw=2.2),
                         Line2D([0], [0], color=_PUB_IXN["salt_neg"], lw=2.2)))
        if "pi" in present_ix:
            ix_h.append(Line2D([0], [0], color=_PUB_IXN["pi"], lw=1.8, ls="--", label="\u03c0\u2013\u03c0 stacking"))
        if "weak" in present_ix:
            ix_h.append(Line2D([0], [0], color=_PUB_IXN["weak"], lw=1.0, ls=":", label="Other contact"))
        if show_halo and (fracs > 0.08).any():
            ix_h.append(Line2D([0], [0], marker="o", ls="none", markersize=10, mfc=_PUB_IXN["halo"],
                               mec="none", alpha=0.7, label="Solvent-exposed atom"))
        from matplotlib.legend_handler import HandlerTuple
        ix_labels = [h.get_label() if not isinstance(h, tuple) else "Salt bridge" for h in ix_h]
        r1 = fig.legend(handles=cls_h, loc="center", bbox_to_anchor=(0.5, 0.80 / Hd), ncol=len(cls_h),
                        fontsize=7.8, frameon=False, handletextpad=0.3, columnspacing=1.1, numpoints=1)
        fig.add_artist(r1)
        if ix_h:
            fig.legend(handles=ix_h, labels=ix_labels, loc="center", bbox_to_anchor=(0.5, 0.46 / Hd),
                       ncol=len(ix_h), fontsize=7.8, frameon=False, handletextpad=0.5, columnspacing=1.1,
                       numpoints=1, handlelength=2.4, handler_map={tuple: HandlerTuple(ndivide=2, pad=0)})
        foot = "Residues within 4.5 \u00c5 of the ligand; interactions are distance-based (no angle criteria); " \
               "arrows point to the H-bond acceptor; distances in \u00c5."
        if omitted:
            foot += f" {omitted} more contact residue(s) not drawn."
        fig.text(0.5, 0.12 / Hd, foot, ha="center", va="center", fontsize=6.6, color="#777777")

        out = {}
        for fmt in ("svg", "pdf"):
            b = io.BytesIO()
            fig.savefig(b, format=fmt, facecolor="white")
            out[fmt] = b.getvalue()
        b = io.BytesIO()
        fig.savefig(b, format="png", dpi=110, facecolor="white")
        out["preview"] = b.getvalue()
        b = io.BytesIO()
        fig.savefig(b, format="png", dpi=int(dpi), facecolor="white")
        out["png"] = b.getvalue()
    out["n_shown"], out["n_omitted"] = len(items), omitted
    out["px"] = (int(round(Wd * dpi)), int(round(Hd * dpi)))
    return out


